export const RESOURCES = [{"id":"wS3PQcWURi-vUKg9n7rSyg","name":"Adult Gay Male 18+ Friendship Circle","cat":"Support Circles","county":"Salt Lake County","counties":["Salt Lake County","Utah County","Washington County"],"demo":["Gay Men"],"img":"https://hosting.photobucket.com/images/i/lgbtqut/Encircle_Logo.png","desc":"This friendship circle is for adults (18+) that identify as gay and male.\n\nFriendship Circles? \n\nThese groups are designed to provide a connection with folx you identify with and help you manage the trials you encounter every day. Friendship Circles create an opportunity for you to take control and thrive in your own life. Friendship Circles provide opportunities for sharing, connection, and support by discussing issues and experiences relevant to each group, often exploring the intersectionality of conservative cultures, spirituality, sexuality, social issues, transitional issues, and health issues and how it impacts us. The groups also provide a great support network—members in similar circumstances with similar feelings with whom they can share in an open and unedited fashion. \n\nGroups organized by sexuality, age, and/or gender identity.\n\nFor schedules and more information, please vis","web":"","tel":"","email":"","addr":"","fb":"","ig":""},{"id":"Feys3ZGoRG-upYBwcDRwjg","name":"Advanced Awareness Counseling","cat":"Mental Health/Counseling","county":"Salt Lake County","counties":["Salt Lake County","Utah County"],"demo":[],"img":"https://hosting.photobucket.com/images/i/lgbtqut/61148a83af542c52d9760291_196587-1724580-3_320x400.jpg","desc":"We consist of a network of qualified mental health providers who have been selected for outstanding educational credentials, experience in the field, exceptional client care principles, high integrity, and expertise in particular areas of specialty.\n\nOur various practitioners have proficiency in faith transitions, minority concerns, marriage counseling, couples counseling, family therapy, PTSD and trauma-related conditions (including EMDR therapy), generalized anxiety and social anxiety, gender dysphoria, gender and transgender specialized care, depression, suicide prevention, bipolar disorder, borderline personality disorder, adolescents and children, play therapy, sand tray therapy, anger management, grief and loss, and much more.\n\nOur facility and our counselors are an ally to the LGBTQ+ community, and we provide support and affirming counseling for individuals of all orientations, id","web":"advancedawarenesscounseling.com","tel":"(385) 455-3768","email":"","addr":"","fb":"","ig":""},{"id":"IqikfxE6ScuYfDS1mzcgtw","name":"Aromantic/Asexual Adult Friendship Circle","cat":"Support Circles","county":"Salt Lake County","counties":["Salt Lake County","Utah County","Washington County"],"demo":["Asexual"],"img":"https://hosting.photobucket.com/images/i/lgbtqut/Encircle_Logo.png","desc":"This friendship circle is for adults (18+) who identify on the spectrum of Aromantic/Asexual. \n\nFriendship Circles?\n\nThese groups are designed to provide a connection with folx you identify with and help you manage the trials you encounter every day. Friendship Circles create an opportunity for you to take control and thrive in your own life. Friendship Circles provide opportunities for sharing, connection, and support through discussion of issues and experiences relevant to each group, often exploring the intersectionality of conservative cultures, spirituality, sexuality, social issues, transitional issues, and health issues and the ways it impacts us. The groups also provide a great support network—members in similar circumstances with similar feelings with whom they can share in an open and unedited fashion.\n\nGroups organized by sexuality, age, and/or gender identity.\n\nFor schedules ","web":"","tel":"","email":"","addr":"","fb":"","ig":""},{"id":"XybNN39fTlquRKw5Bwnx8g","name":"Asexual/Aromantic Umbrella Mormons Online Community","cat":"Online Community","county":"","counties":[],"demo":["Asexual"],"img":"https://hosting.photobucket.com/images/i/lgbtqut/5f663c89dc4ac15aa61147df_novo-logo-afirma_o_n.png","desc":"An online community by Affirmation. For those within the asexual or aromantic umbrella.","web":"","tel":"","email":"","addr":"","fb":"https://www.facebook.com/groups/130720233784404/","ig":""},{"id":"idG9YJCGSFy1Mbb7jNfxFw","name":"Ben There, Done That","cat":"Blog","county":"","counties":[],"demo":["LDS"],"img":"https://storage.googleapis.com/glide-prod.appspot.com/uploads-v2/NSfaaNV0fRhAK9yZqEUi/pub/GOYdUbtbqiUsCSb70KcL.png","desc":"\"Questions from the Closet\" Co-Host Ben Schilaty's personal blog. He discusses his journey of staying active in the church and broadly sharing his life story as a gay Mormon.","web":"benschilaty.blogspot.com","tel":"","email":"","addr":"","fb":"","ig":""},{"id":"LTHYCav1RKa.N41aFE4wlg","name":"Bi/Pan Adults Friendship Circle","cat":"Support Circles","county":"Salt Lake County","counties":["Salt Lake County","Utah County","Washington County"],"demo":["Bi/Pansexual"],"img":"https://hosting.photobucket.com/images/i/lgbtqut/Encircle_Logo.png","desc":"This friendship circle is for adults (18+) who identify as bisexual or pansexual. \n\nFriendship Circles?\nThese groups are designed to provide a connection with folx you identify with and help you manage the trials you encounter every day. Friendship Circles create an opportunity for you to take control and thrive in your own life.\n\nFriendship Circles provide opportunities for sharing, connection, and support through discussion of issues and experiences relevant to each group, often exploring the intersectionality of conservative cultures, spirituality, sexuality, social issues, transitional issues, and health issues and the ways it impacts us. The groups also provide a great support network—members in similar circumstances with similar feelings with whom they can share in an open and unedited fashion.\n\nGroups organized by sexuality, age, and/or gender identity.\n\nFor schedules and more inf","web":"","tel":"","email":"","addr":"","fb":"","ig":""},{"id":"itZMhomnTdS3yZMeahr.wQ","name":"BW Bastian Foundation","cat":"Business","county":"","counties":[],"demo":[],"img":"https://hosting.photobucket.com/images/i/lgbtqut/5f563d9be36f1b167826fa82_5f356c7856e21ab3badfc63b_BW_20Bastian.png","desc":"The B.W. Bastian Foundation strives to build community and understanding by supporting local and national institutions. Financial support is directed to the Arts through educational outreach. A strong commitment is placed on programs and organizations that benefit, encourage, and preserve the rights of individuals, promote equality for the LGBTQ+ community and HIV/AIDS programs. The B.W. Bastian Foundation only supports organizations who wholeheartedly embrace the principle of equality. As such, each organization must include a statement specifically stating their commitment to equality for all Americans, including the gay and lesbian community, in their application.","web":"bastianfoundation.org","tel":"","email":"","addr":"","fb":"","ig":""},{"id":"bxyxcGmkSES3tSvhUSG9LA","name":"BYU USGA","cat":"Other","county":"","counties":[],"demo":[],"img":"https://hosting.photobucket.com/images/i/lgbtqut/5f5637d8c04fcd0094f27b14_5f2d99dcfeb406f686539c20_USGA.jpeg","desc":"Welcome to USGA! \n\nUnderstanding Sexuality, Gender, and Allyship (USGA) is an unofficial group of Brigham Young University students, faculty, and guests who wish to enhance the BYU community by providing a safe space for open, respectful conversation on LGBTQ & SSA topics. USGA is a place of refuge and our priority is to have compassion and to seek understanding through listening. Harassment or antagonism against any person or organization will not be tolerated. Members are asked to be mindful of USGA’s political neutrality and to be respectful of BYU, The Church of Jesus Christ of Latter-Day Saints, and the beliefs and experiences of others. In order to maintain a safe and welcoming environment, USGA supports its members in upholding the Honor Code, and expects all participants to be respectful of others’ names, pronouns, and identities. They encourage all not to make assumptions or ask","web":"www.usgabyu.com","tel":"","email":"byu.usga@gmail.com","addr":"1230 Bulldog Ave. Provo, UT 84604","fb":"https://www.facebook.com/UsgaAtByu/","ig":""},{"id":"YflgqyezRr-Hp3.MgLuANA","name":"Cache Pride Center","cat":"Pride Center","county":"Cache County","counties":["Cache County"],"demo":[],"img":"https://hosting.photobucket.com/images/i/lgbtqut/5f5633d7e36f1b64ac26e98c_5f358fc72b040487de0d14ba_Cache_20Pride.jpeg","desc":"Cache Pride Center is a program of the Cache Valley Unitarian Universalists Church and is committed to transforming and supporting Lesbian, Gay, Bisexual, Transgender, Queer, Pansexual, plus (LGBTQIAP+) Cache Valley communities through support groups, comprehensive programming, suicide prevention, mentoring, community advocacy, and community training devised to promote positive outlooks and changes within underserved populations. \n\n- Groups: Cache Pride Center has groups/programs for preteens, teens, transgender individuals, & LGBTQ+ adults.\n- Parent Support: We know it is important for LGBTQ+ persons to have support. Cache Pride Center offers parent support group services\n- We offer have other services for those in need of food, clothing, hygiene items, and temporary housing/shelter. \n- We assist in finding health care and mental health professionals.","web":"cachepridecenter.org","tel":"","email":"info@cachepridecenter.org","addr":"596 E 900 N, Logan, UT 84321","fb":"https://www.facebook.com/CachePrideCenter/","ig":""},{"id":"ym.DNrDaTFGdcpMYPnJi8w","name":"CDC National Info Hotline","cat":"Wellness/Medical","county":"","counties":[],"demo":[],"img":"https://hosting.photobucket.com/images/i/lgbtqut/5f5638fbca15840081e624c4_5f2e1292de355b3d44088f9a_CDC-Logo20Edited.jpeg","desc":"CDC’s national health information hotline provides answers to your questions regarding HIV, how to protect yourself, and where to get an HIV test. In English, en Español, 8 am to 8 pm ET, Monday through Friday.","web":"","tel":"1-888-232-6348","email":"","addr":"","fb":"","ig":""},{"id":"wRpZolU.RYa7.8LL4j8NQg","name":"Celebrate Therapy","cat":"Mental Health/Counseling","county":"Utah County","counties":["Utah County"],"demo":[],"img":"https://storage.googleapis.com/glide-prod.appspot.com/uploads-v2/GLyS34gJTOtHtpGe05Cl/pub/kJF0rI9AnP2lEf9CYEfG.png","desc":"Celebrate Therapy is the first clinic in Provo, Utah and the surrounding area that is owned and run by a team of queer clinicians. We work to support clients in becoming confident and supported in their own queerness. We’ll also work alongside family members who are working through how to support their queer loved ones. We are hoping to lead a transformational change Utah County and beyond!","web":"https://www.celebratetherapy.org/","tel":"(801) 448-7712","email":"","addr":"286 W. Center St, Provo, UT 84601","fb":"","ig":"https://www.instagram.com/celebratetherapy/"},{"id":"n7PV3lEJRLOwkHZx5X49Qw","name":"Cheer Salt Lake","cat":"Social Groups","county":"Salt Lake County","counties":["Salt Lake County"],"demo":[],"img":"https://storage.googleapis.com/glide-prod.appspot.com/uploads-v2/GLyS34gJTOtHtpGe05Cl/pub/3rAsggbnYrS9JNUYX1pe.png","desc":"Founded in 2011, Cheer Salt Lake raises funds and awareness for those living with life-challenging conditions in the LGBTQ community and beyond. We're an inclusive team that welcomes volunteers from all backgrounds and partners with a variety of community organizations in Salt Lake, Provo, and Ogden. We're a federal 501(c)3 non-profit and registered charity in the state of Utah.","web":"cheersaltlake.org","tel":"(415) 745-0923","email":"info@cheersaltlake.org","addr":"","fb":"https://www.facebook.com/cheersaltlake/","ig":"https://www.instagram.com/cheersaltlake/"},{"id":"cwTKvQXGTPeQXY81zyYLZg","name":"Children's Service Society of Utah","cat":"Professional Services","county":"Salt Lake County","counties":["Salt Lake County"],"demo":["Families/Youth"],"img":"https://storage.googleapis.com/glide-prod.appspot.com/uploads-v2/vZEd46xUe6vz0E68sGvW/pub/khGexBFNlQHEJrkPEYeh.png","desc":"Children’s Service Society of Utah empowers families and caregivers through services that support the safety and well-being of children. CSS is the oldest non-denominational child welfare and family support agency in Utah. Through the years Children’s Service Society has evolved its programs according to the needs of the children and families they serve in the community. Today Children’s Service Society of Utah empowers families and caregivers through services that support the safety and well-being of children. This is accomplished through these programs: Adoption, Grandfamilies Kinship Care, Care About Childcare and Utah Parents in Action, Home Visitation.","web":"cssutah.org","tel":"801-355-7444","email":"","addr":"655 East 4500 South, Suite 200","fb":"https://www.facebook.com/ChildrensServiceSociety","ig":"https://www.instagram.com/cssutah/"},{"id":"xwkyEW5LTH2fCtNfl2H-Tg","name":"Cougar Pride","cat":"College Resources","county":"Utah County","counties":["Utah County"],"demo":["LGBTQ Adult"],"img":"https://hosting.photobucket.com/images/i/lgbtqut/6205d999787f5a57c61009ba_a16184fe-a0be-400b-af1e-8217e8dde010.png","desc":"Cougar Pride Center aims to empower queer BYU students, celebrate progress, and advocate for change through collaborative activism. Founded in 2021, we are a volunteer-run organization that strives to create community and care for LGBTQ+ individuals on campus.","web":"cougarpridecenter.org","tel":"","email":"cougarpridecenter@gmail.com","addr":"","fb":"https://www.facebook.com/cougarpridecenter","ig":"instagram.com/cougarpridecenter"},{"id":"7pp3DPUvSEKGajNY2s2KNA","name":"Creating Community - LGBTQ & Allies","cat":"FHE/Sunday Service","county":"Davis County","counties":["Davis County"],"demo":["LDS"],"img":"https://hosting.photobucket.com/images/i/lgbtqut/6178b3b8a19f8b75c14f01be_Copy_of_Copy_of_Unnamed_Design.png","desc":"A space for LGBTQ people and their loved ones. We are here to share a connection, friendship, and support. We have a get-together on the fourth Sunday of each month in Davis County, Utah.","web":"","tel":"","email":"","addr":"","fb":"https://www.facebook.com/groups/1492727134249314/","ig":""},{"id":"4mhrIN0DSJyuTPUo2tuBfA","name":"Damn These Heels","cat":"Publications/Media","county":"","counties":[],"demo":[],"img":"https://hosting.photobucket.com/images/i/lgbtqut/5fac1405b22c78f75bed23ec_Damn_these_heels.jpg","desc":"The annual film festival explores LGBTQ issues, ideas, and art through showcasing dramatic and documentary films from around the world. Damn These Heels remains a community focused, grassroots, locally-produced festival with strong community partnerships.","web":"https://www.utahfilmcenter.org/","tel":"","email":"","addr":"","fb":"","ig":""},{"id":"M780wDVXRTCbahEP3GXBUw","name":"Dixie State LGBTQ+ Resource Center","cat":"College Resources","county":"Washington County","counties":["Washington County"],"demo":[],"img":"https://hosting.photobucket.com/images/i/lgbtqut/5fb1a52fdc2686a1709f58b6_Dixie_State_GSA.jpg","desc":"Our mission is to promote understanding and acceptance for all individuals by education, activities, and service for the campus and larger community. The club provides support and social networking for all persuasions of people. We want to raise awareness about suicide rates and promote education of homosexuality and acceptance for equality in Saint George.\n\nWHAT WE DO\n\nThe Resource Center empowers the LGBTQ+ people who are part of DSU’s community. Much of this comes from the simple act of providing information to everyone. Other parts of the center’s mission include scholarships, mentoring, promoting visibility and acceptance, and outreach. We create a space for students where they feel safe to gather, express themselves, discuss ideas, learn, and teach others. We work as a team to improve LGBTQ+ inclusion across campus.\n\n- Education\n- Safe Zone Training\n- Mentoring Support\n- Peer Suppo","web":"https://lgbt.dixie.edu/","tel":"435-652-7752","email":"lgbtq@dixie.edu","addr":"261 S 900 E #207, St. George, UT 84770","fb":"https://www.facebook.com/groups/dixiegsa/","ig":""},{"id":"cmtjNgreRdWFk--O4vXK0g","name":"Dragon Dads","cat":"Other","county":"","counties":[],"demo":["Parent"],"img":"https://hosting.photobucket.com/images/i/lgbtqut/5f563220c13ff61101bfe559_5f2e131ed336660bfd9a8e26_Dragon_20Dads.png","desc":"We fight to prevent teen suicide and to provide support and education to other fathers who want to show love and support for their LGBTQIA+ children.If you would like more information or would like to join, please click below to begin the process.","web":"","tel":"","email":"","addr":"","fb":"https://www.facebook.com/groups/dragondads/","ig":""},{"id":"Zvd.MoggSMeqRU76qbZg9g","name":"Emmaus LGBTQ Ministry","cat":"Online Community","county":"","counties":[],"demo":["LDS","Allies"],"img":"https://hosting.photobucket.com/images/i/lgbtqut/351855910_643312370634812_3848817731976547444_n.png","desc":"Emmaus fosters and supports ministry to and with LGBTQ individuals and their families in and adjacent to The Church of Jesus Christ of Latter-day Saints.\n\nEmmaus is a community of heterosexual/cisgender and LGBTQ Latter-day Saints who are called to ministry for the safety, well-being and happiness of LGBTQ people in and adjacent to The Church of Jesus Christ.\n\nWe envision communities, congregations and families where LGBTQ individuals know they are cherished, where they are free from discrimination and inequality, where they are fully heard, understood and protected, and where their agency is respected.\n\nWe feel driven to do this work by our testimonies of the Gospel. We know there is a place in Christ’s Church and in our Heavenly Parents’ plan for every single one of us, and our hearts ache for the anguish caused by misunderstanding and lack of knowledge.\n\nWe believe that the way forwar","web":"emmauslgbtq.org","tel":"","email":"","addr":"","fb":"https://www.facebook.com/groups/emmauslgbtq/","ig":""},{"id":"cJ00BaioRA-VPJPA8I.JGg","name":"Encircle Provo","cat":"Pride Center","county":"Utah County","counties":["Utah County"],"demo":["Youth"],"img":"https://hosting.photobucket.com/images/i/lgbtqut/60fae9494cd60f1a5fb4331d_218384456_867797794136825_712167177273530856_n.png","desc":"","web":"","tel":"","email":"","addr":"","fb":"","ig":""},{"id":"I.DpcfncSs-2oEGxiJF4ag","name":"Encircle Salt Lake","cat":"Pride Center","county":"Salt Lake County","counties":["Salt Lake County"],"demo":["Youth"],"img":"https://storage.googleapis.com/glide-prod.appspot.com/uploads-v2/NSfaaNV0fRhAK9yZqEUi/pub/JxMoQgrgY2YkgVnpnB07.png","desc":"","web":"","tel":"","email":"","addr":"","fb":"","ig":""},{"id":"8nnixaVnSF-hsPNkuwt2dA","name":"Encircle St. George","cat":"Pride Center","county":"Washington County","counties":["Washington County"],"demo":["Youth"],"img":"https://hosting.photobucket.com/images/i/lgbtqut/60fae9a7d3f1f71629a45f99_219479815_878659989722201_322750248107661649_n.png","desc":"","web":"","tel":"","email":"","addr":"","fb":"","ig":""},{"id":"gpE2VUOtRGmhtpKu8RBEXA","name":"Equality Utah","cat":"Education/Advocacy","county":"Salt Lake County","counties":["Salt Lake County"],"demo":[],"img":"https://hosting.photobucket.com/images/i/lgbtqut/5fb96adfcdd292cdcc7806c5_Equality_utah.png","desc":"Equality Utah works to build a community where every Utahn is valued for being who they are regardless of sexual orientation or gender identity. We believe everyone in our state deserves to be treated with respect and understanding and to be afforded the same basic freedoms and opportunities as everyone else.\n\nOUR VISION: A fair and just Utah. OUR MISSION: To secure equal rights and protections for lesbian, gay, bisexual, transgender and queer Utahns and their families.\n\nOUR ISSUES: \nNondiscrimination\nLGBTQ Families\nVictim Targeting\nLGBTQ Youth\nTransgender Utahns\nSuicide Prevention","web":"equalityutah.org","tel":"801-355-3479","email":"info@equalityutah.org","addr":"175 200 S #1004, Salt Lake City, UT 84101","fb":"https://www.facebook.com/EqualityUtah","ig":"https://www.instagram.com/equalityutah/"},{"id":"m800StjxS4qBVsDklvyXAw","name":"Family Acceptance Project","cat":"Research","county":"","counties":[],"demo":["Parent"],"img":"https://hosting.photobucket.com/images/i/lgbtqut/5f693891f8dc32460437cc17_Untitled_design_(2).png","desc":"The Family Acceptance Project® is a research, intervention, education and policy initiative that works to prevent health and mental health risks for lesbian, gay, bisexual and transgender (LGBTQ) children and youth, including suicide, homelessness, drug use and HIV – in the context of their families, cultures and faith communities. We use a research-based, culturally grounded approach to help ethnically, racially and religiously diverse families learn to support their LGBTQ children.Our team has put research into practice by developing an evidence-based family model of wellness, prevention and care to strengthen families and promote positive development and healthy futures for LGBTQ children and youth. We provide training and consultation on our family-based prevention and intervention approach across the United States and in other countries.","web":"familyproject.sfsu.edu","tel":"","email":"fap@sfsu.edu","addr":"","fb":"","ig":""},{"id":"5XGNcHPvQ8atsvA5n5OFkw","name":"Family Solutions Counseling","cat":"Mental Health/Counseling","county":"Cache County","counties":["Cache County"],"demo":[],"img":"https://hosting.photobucket.com/images/i/lgbtqut/6173206ad2718886817d3532_66262393_411908376084012_2964773000525643776_n.png","desc":"LGBTQIAP+ ALLIED\n\nSupporting you\n\nAs a practice that focuses on being inclusive and affirmative to the LGBTQIAP+ community, we have created this resource page with you in mind. While all of our therapists are accepting of LGBTQIAP+, those with particular experience and ability to be affirmative are listed here.\n\nAutumn Abbott, MSWI\n\nBeth Allred, CSW\n\nRobin Hunt, LCSW\n\nRachel White, CSW\n\nEvelyn Tovar, CSW-I\n\nSkyler Taylor, CSW\n\nStacie Later, CSW\n\nLauren Harrigian, ACMH\n\nProud member of the LGBTQ-Affirmative Psychotherapist Guild of Utah Inc.","web":"familysolutionsutah.org","tel":"435-799-5035","email":"info@familysolutionsutah.org","addr":"115 Golf Course Road Suite E Logan,UT 84321","fb":"https://www.facebook.com/familysolutionsutah/","ig":""},{"id":"rYQDtR8EQCCv6ffZRcPsgg","name":"Fathers in Affirmation Online Community","cat":"Online Community","county":"","counties":[],"demo":["Parent"],"img":"https://hosting.photobucket.com/images/i/lgbtqut/5f663c89dc4ac15aa61147df_novo-logo-afirma_o_n.png","desc":"For those who are gay fathers or would be fathers.","web":"","tel":"","email":"","addr":"","fb":"https://www.facebook.com/groups/470473746493580/","ig":""},{"id":"2.u53pD-QE-tRWNskcclLQ","name":"FHE for All Cache Valley","cat":"FHE/Sunday Service","county":"Cache County","counties":["Cache County"],"demo":["LDS"],"img":"https://hosting.photobucket.com/images/i/lgbtqut/5f564238b0505c3613b7d071_Untitled_design_(1).png","desc":"A gathering of friends, family and individuals with ties to the LGBTQ community where we meet monthly to share in fellowship, song, and refreshment- FHE style. Our goal is to affirm faith and facilitate space for healing and encouragement for ALL: Allies, LGBTQ and Leaders of the Church of Jesus Christ of Latter-Day Saints here in Cache Valley. For information and access, please contact Jenny Mathews or Sue Hendricks below.","web":"","tel":"","email":"","addr":"","fb":"","ig":"https://instagram.com/fheforall_cachevalley?igshid=1hjkd3qn298x3"},{"id":"zkWUDnDPTnS2fxG3GbQxRw","name":"First Step House","cat":"Mental Health/Counseling","county":"Salt Lake County","counties":["Salt Lake County"],"demo":[],"img":"https://storage.googleapis.com/glide-prod.appspot.com/uploads-v2/vZEd46xUe6vz0E68sGvW/pub/DRDsngDiPDfs3mEHc9zx.png","desc":"We offer a suite of patient-centered and evidenced-based programs that span a continuum of care across pre-treatment, treatment entry, recovery initiation, housing, employment, and long-term recovery management.","web":"https://firststephouse.org","tel":"801-359-8862 ext. 2129","email":"","addr":"440 E. 500 S Salt Lake City, Utah 84102","fb":"https://www.facebook.com/firststephouse","ig":""},{"id":"eSeMeX7zQWCzbnQOytWJDw","name":"Flourish Therapy","cat":"Mental Health/Counseling","county":"Utah County","counties":["Utah County","Davis County","Salt Lake County"],"demo":[],"img":"https://hosting.photobucket.com/images/i/lgbtqut/5fa5e1cd79f25bc54ed2dd82_cropped-Copy-of-Flourish-Icon.png","desc":"Flourish Therapy is a 501(c)(3) non -profit organization that provides subsidized therapy for LGBTQ clients and offers a wide variety of therapy options including: individual, couples, family and group counseling for all age groups, including short- and long-term counseling, crisis intervention, parent intervention, and support services with a focus on quality care for LGBTQ clients and their families. They finance more than 100 free sessions a month and 75% of their clients pay less than $50.00 per session. The clinical staff includes culturally competent licensed mental health practitioners, marriage and family therapists and counselors. Flourish works with several insurances, including Select Health, PEHP, EMI and DMBA. Flourish Therapy is based in Utah county, with therapy services offered across, Utah, Davis, and Salt Lake counties.","web":"flourishtherapy.org","tel":"385-309-1038","email":"info@flourishtherapy.org","addr":"1426 E 820 N, Orem, UT 84097","fb":"https://www.facebook.com/flourishtherapyinc/","ig":""},{"id":"PoD.2Pv7SOCsrclEza7j1g","name":"Food & Friends Cache Valley","cat":"Social Groups","county":"Cache County","counties":["Cache County"],"demo":["Gay Men"],"img":"https://hosting.photobucket.com/images/i/lgbtqut/5f5634b6386cb4186df1b6ee_5f2e13894563bb3639285413_Food20Friends20Edited.jpeg","desc":"We are a gay men's social group in the Cache Valley that meets monthly for dinner, conversation, board games, and/or movie nights. We meet on 2nd Saturday of every month at 6 PM either at a local restaurant (different restaurant each month) or at a member's house for potluck dinner. Join us to try food from different restaurants in Cache Valley while making new friends or catching up with old ones.We welcome all gay/bi/trans men, 18 yrs and up. We don't have to be residents of Cache Valley as we have friends from SLC that had attended our gatherings. We are a friendly, supportive and are nonjudgmental group of like-minded men who like trying different cuisines and have fun socializing. We ask that everyone be respectful as some of our members may not be \"out\".","web":"","tel":"","email":"","addr":"","fb":"https://www.facebook.com/groups/loganfoodandfriends/","ig":""},{"id":"nusCmgC.TViJNbIBViQlUQ","name":"For The Strength of LGBTQ & SSA Youth Online Community","cat":"Online Community","county":"","counties":[],"demo":["Youth"],"img":"https://hosting.photobucket.com/images/i/lgbtqut/5f663c89dc4ac15aa61147df_novo-logo-afirma_o_n_(1).png","desc":"The Facebook page listed below is a portal for the For the Strength of LGBTQ/SSA Youth Facebook group which is \"Secret.\" The group is specifically for straight and LGBTQ/SSA LDS youth ages 12-18 to support one another and is moderated by LDS youth with the supervision of a few straight/cis parents and two LDS therapists. If you are a youth age 12-18 and would like to join, leave a message with the page or email below.","web":"","tel":"","email":"fsymod@gmail.com","addr":"","fb":"https://www.facebook.com/pages/For-the-Strength-of-LGBTQ-SSA-Youth/1454433078181817","ig":""},{"id":"IF-R53t2QQGmsJJdDu5uag","name":"Fourth Street Clinic","cat":"Wellness/Medical","county":"Salt Lake County","counties":["Salt Lake County"],"demo":[],"img":"https://hosting.photobucket.com/images/i/lgbtqut/61148eb234645f19f9e35c8f_fourth.jpg","desc":"","web":"fourthstreetclinic.org","tel":"801-364-0058","email":"info@fourthstreetclinic.org","addr":"409 West 400 South, Salt Lake City, Utah 84101","fb":"https://www.facebook.com/FourthStreetClinic/","ig":"https://www.instagram.com/4thstreetclinic/"},{"id":"VMbAOidgTdyaYXNUhVsc5Q","name":"Full Circle Wellness Center","cat":"Social Groups","county":"Cache County","counties":["Cache County"],"demo":[],"img":"https://hosting.photobucket.com/images/i/lgbtqut/5fb544bc0c4524dde879ec03_74620919_150459412994725_5498206812085682176_o_(1).png","desc":"Full Circle Wellness Center host various monthly LGBTQ events at their center including yoga meetups, business cultural competency trainings, potlucks, etc. Full Circle Wellness Center is also an LGBTQ friendly business offering Ionic foot detox baths, reiki, foot zoning, light therapy, wellness related classes, meditation circles, nutritional therapy, message, tarot reading and health/wellness products.","web":"","tel":"435-720-1096","email":"fullcirclewellnesscenter.ut@gmail.com","addr":"60 S Main St Suite 101, Brigham City, UT 84302","fb":"https://www.facebook.com/fullcirclewellnessutah/?ref=page_internal","ig":""},{"id":"hNoTLhsfRay9lR0usGZayw","name":"Full Spectrum Coaching","cat":"Professional Services","county":"Salt Lake County","counties":["Salt Lake County","Utah County"],"demo":[],"img":"https://hosting.photobucket.com/images/i/lgbtqut/61781f7497015f3f2397a810_Copy_of_Unnamed_Design.png","desc":"","web":"","tel":"801-872-3394","email":"trh.fullspectrumcoaching@gmail.com","addr":"","fb":"","ig":"https://www.instagram.com/coach_tay1/"},{"id":"EzWOzMFwQ9CsQCcRifnN3Q","name":"Gay Latter Day Saint Crossroads","cat":"Other","county":"","counties":[],"demo":["LDS"],"img":"https://hosting.photobucket.com/images/i/lgbtqut/60b4fe32eacdd873063e6ff4_Gay_Latter-Day_Saint_Crossroads.png","desc":"Evan Smith believed the anti-gay messages he heard in church during his childhood, which contributed to some negative experiences on his mission in San Francisco. Later, as a bishop and then a counselor in a stake presidency,his heart softened as church members came to him seeking guidance about feeling attracted to others of the same gender. Evan’s investigating and study became personal when his own son came out as gay.In this navigable e-book, Evan tackles the issues with a lawyer’s mind and a penetrating analysis of scriptures and church doctrine. He addresses such questions as these: “What insights apply from the end of polygamy and the racebased priesthood/temple ban?” “Why do I stay in the church?” and, most importantly, “What words are hurtful/helpful to LGBTQ people and their families?”","web":"https://www.gayldscrossroads.org/","tel":"","email":"contact@gayldscrossroads.org","addr":"","fb":"https://www.facebook.com/GayLDSCrossroads/","ig":""},{"id":"Rr5NUCyeT7KNHsQFr67Xbw","name":"GB: Parents of Trans Kids (On Hiatus)","cat":"Support Circles","county":"Utah County","counties":["Utah County"],"demo":["Parent","Trans"],"img":"https://hosting.photobucket.com/images/i/lgbtqut/5f2b30c0782f831652b5c0a7_Genderbands.png","desc":"Hey there, friends. Genderbands has an announcement. \n\nWe are taking a temporary hiatus from most of our services so we can come back stronger and better equipped to meet the needs of our beloved transgender community. We know this may feel disappointing to some of you, but we are committed to our mission of helping transgender people pay for transition-related costs, and pausing to regroup is a necessary step in continuing our work. Here are a few things you can expect during our hiatus:\n \nGrant applications will open in the Fall of 2023, and the next grant recipients will be announced in 2024.\nOur retail store will continue to operate on a limited basis.\nWe are no longer accepting new applications for our free binder program, but we will do our best to honor all applications we have already received. \nEmail response time will be slower than typical during the hiatus.\nYou will still fin","web":"genderbands.org/hiatus","tel":"","email":"","addr":"","fb":"","ig":""},{"id":"Z21p3SgKQOCJranjwa6qeQ","name":"GB: Saturday Socials (On Hiatus)","cat":"Social Groups","county":"Utah County","counties":["Utah County"],"demo":["Trans"],"img":"https://hosting.photobucket.com/images/i/lgbtqut/5f2b30c0782f831652b5c0a7_Genderbands.png","desc":"Hey there, friends. Genderbands has an announcement. \n\nWe are taking a temporary hiatus from most of our services so we can come back stronger and better equipped to meet the needs of our beloved transgender community. We know this may feel disappointing to some of you, but we are committed to our mission of helping transgender people pay for transition-related costs, and pausing to regroup is a necessary step in continuing our work. Here are a few things you can expect during our hiatus:\n \nGrant applications will open in the Fall of 2023, and the next grant recipients will be announced in 2024.\nOur retail store will continue to operate on a limited basis.\nWe are no longer accepting new applications for our free binder program, but we will do our best to honor all applications we have already received. \nEmail response time will be slower than typical during the hiatus.\nYou will still fin","web":"genderbands.org/hiatus","tel":"","email":"","addr":"","fb":"https://www.facebook.com/genderbands/","ig":"https://www.instagram.com/genderbands/"},{"id":"IWloZ3nDTwygP2LcA2KA2g","name":"GB: Trans 18+ (On Hiatus)","cat":"Support Circles","county":"Utah County","counties":["Utah County"],"demo":["Trans"],"img":"https://hosting.photobucket.com/images/i/lgbtqut/5f2b30c0782f831652b5c0a7_Genderbands.png","desc":"Hey there, friends. Genderbands has an announcement. \n\nWe are taking a temporary hiatus from most of our services so we can come back stronger and better equipped to meet the needs of our beloved transgender community. We know this may feel disappointing to some of you, but we are committed to our mission of helping transgender people pay for transition-related costs, and pausing to regroup is a necessary step in continuing our work. Here are a few things you can expect during our hiatus:\n \nGrant applications will open in the Fall of 2023, and the next grant recipients will be announced in 2024.\nOur retail store will continue to operate on a limited basis.\nWe are no longer accepting new applications for our free binder program, but we will do our best to honor all applications we have already received. \nEmail response time will be slower than typical during the hiatus.\nYou will still fin","web":"genderbands.org/hiatus","tel":"","email":"","addr":"","fb":"","ig":""},{"id":"KZCytj68RrOkhVkuwXvM2Q","name":"GB: Trans Over 40 (On Hiatus)","cat":"Support Circles","county":"Utah County","counties":["Utah County"],"demo":["Trans"],"img":"https://hosting.photobucket.com/images/i/lgbtqut/5f2b30c0782f831652b5c0a7_Genderbands.png","desc":"Hey there, friends. Genderbands has an announcement. \n\nWe are taking a temporary hiatus from most of our services so we can come back stronger and better equipped to meet the needs of our beloved transgender community. We know this may feel disappointing to some of you, but we are committed to our mission of helping transgender people pay for transition-related costs, and pausing to regroup is a necessary step in continuing our work. Here are a few things you can expect during our hiatus:\n \nGrant applications will open in the Fall of 2023, and the next grant recipients will be announced in 2024.\nOur retail store will continue to operate on a limited basis.\nWe are no longer accepting new applications for our free binder program, but we will do our best to honor all applications we have already received. \nEmail response time will be slower than typical during the hiatus.\nYou will still fin","web":"genderbands.org/hiatus","tel":"","email":"","addr":"","fb":"","ig":""},{"id":"gTdyVzWvRUW6K9bc-gAFPA","name":"GB: Trans Youth (On Hiatus)","cat":"Support Circles","county":"Utah County","counties":["Utah County"],"demo":["Trans","Youth"],"img":"https://hosting.photobucket.com/images/i/lgbtqut/5f2b30c0782f831652b5c0a7_Genderbands.png","desc":"Hey there, friends. Genderbands has an announcement. \n\nWe are taking a temporary hiatus from most of our services so we can come back stronger and better equipped to meet the needs of our beloved transgender community. We know this may feel disappointing to some of you, but we are committed to our mission of helping transgender people pay for transition-related costs, and pausing to regroup is a necessary step in continuing our work. Here are a few things you can expect during our hiatus:\n \nGrant applications will open in the Fall of 2023, and the next grant recipients will be announced in 2024.\nOur retail store will continue to operate on a limited basis.\nWe are no longer accepting new applications for our free binder program, but we will do our best to honor all applications we have already received. \nEmail response time will be slower than typical during the hiatus.\nYou will still fin","web":"genderbands.org/hiatus","tel":"","email":"","addr":"","fb":"","ig":""},{"id":"q-x2k1OPTvKlY9WUj-pdBw","name":"GEM Stories","cat":"Blog","county":"","counties":[],"demo":["Trans"],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/60b3adc5e891222c2577c5c2_GEM%20Stories.jpg","desc":"GEM Stories seeks to amplify the voices of gender-expansive Mormons: Latter-day Saints or those adjacent to it, who are also transgender, agender, genderqueer, non-binary, intersex, two-spirit, or otherwise not cisgender.\n\nThis space cultivates support for those of us who are grappling, or have grappled, with tension between our genders, and the doctrines, teachings, and behaviors of LDS Church leaders and members. We acknowledge the unique joys and pains that come with existing in any capacity as a GE Mormon, and we affirm the spiritual paths and individual agency of every gender-expansive person.\n\nOur hope is that in getting to know us better, LDS leaders and members can gain a greater understanding of how to minister to and love their GE siblings— and that other GE individuals will know that they aren't alone.","web":"https://gemstories.org/","tel":"","email":"transgenderdaysaints@gmail.com","addr":"","fb":"https://www.facebook.com/gemormons","ig":"http://instagram.com/gemormons"},{"id":"1uBU7A3hQA2KpVGRZm6wxA","name":"GenderBands (On Hiatus)","cat":"Support Organization","county":"Utah County","counties":["Utah County"],"demo":["Trans"],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5f563c0c8e3cdf1ccfad3d7b_5f2b30c0782f831652b5c0a7_Genderbands.png","desc":"Hey there, friends. Genderbands has an announcement. \n\nWe are taking a temporary hiatus from most of our services so we can come back stronger and better equipped to meet the needs of our beloved transgender community. We know this may feel disappointing to some of you, but we are committed to our mission of helping transgender people pay for transition-related costs, and pausing to regroup is a necessary step in continuing our work. Here are a few things you can expect during our hiatus:\n \nGrant applications will open in the Fall of 2023, and the next grant recipients will be announced in 2024.\nOur retail store will continue to operate on a limited basis.\nWe are no longer accepting new applications for our free binder program, but we will do our best to honor all applications we have already received. \nEmail response time will be slower than typical during the hiatus.\nYou will still fin","web":"genderbands.org/hiatus","tel":"","email":"","addr":"51 West Center St #341 Orem, UT 84057, USA","fb":"https://www.facebook.com/genderbands/","ig":"https://www.instagram.com/genderbands/"},{"id":"7l6IJOCVQ36p0vTUqign-w","name":"Give Back Utah","cat":"Homeless","county":"Utah County","counties":["Utah County","Salt Lake County"],"demo":["Adults"],"img":"https://storage.googleapis.com/glide-prod.appspot.com/uploads-v2/vZEd46xUe6vz0E68sGvW/pub/KfklHmeIDHSnwgQWgqoS.jpeg","desc":"We are a local volunteer service looking to have others join our team to lend a hand to those in need. Our hope is to assist these people who want to become self sufficient and take back control of their lives.","web":"givebackutah.org","tel":"","email":"info@givebackutah.org","addr":"","fb":"https://www.facebook.com/profile.php?id=100068836710139","ig":""},{"id":"fFjyRknJQeWruTArbh7m0w","name":"GLSEN Northern Utah","cat":"Education/Advocacy","county":"","counties":[],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/61148f6c505200cfe17c02e1_default-share-img--facebook.jpg","desc":"GLSEN Northern Utah is a chapter of GLSEN, a national organization fighting for every student’s right to a safe, supportive education. \n\nGLSEN Northern Utah is a grassroots initiative, working locally in our community to ensure safe schools for all students, regardless of sexual orientation and gender identity. There are 43 Chapters around the country doing this important work. Join us today!\nOur chapter supports students and educators locally, organizes around LGBTQ-affirming public policy, plans teacher trainings, and hosts events for students, educators, parents, and allies. Chapters like ours play an important role in bringing GLSEN’s programs and visions to right where we live, work, and learn. While some chapters have full-time or part-time staff, most are entirely volunteer-based. We're always looking for new volunteers to help us ensure safe schools for all students.","web":"https://www.glsen.org/chapter/northern-utah","tel":"","email":"","addr":"","fb":"https://www.facebook.com/GLSEN","ig":"https://www.instagram.com/glsen/"},{"id":"t95Nf0c-StWlc7-TDxI-mw","name":"Health Insurance Provider Search","cat":"Wellness/Medical","county":"","counties":[],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/61148fb34b7aa72bda794aeb_2017-01-13-health-insurance.jpg","desc":"Use the following links below to find in-network providers within your health insurance plan.","web":"","tel":"","email":"","addr":"","fb":"","ig":""},{"id":"V4bYF3FVTr-F5DKdqFGrrg","name":"Help Me Flourish: Parent and Caregiver Support Group","cat":"Support Circles","county":"Utah County","counties":["Utah County","Davis County","Salt Lake County"],"demo":["Parent"],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5fa5e1cd79f25bc54ed2dd82_cropped-Copy-of-Flourish-Icon.png","desc":"Christine Hubbard, Social Work Associate at Flourish Therapy, hosts an educational support group for parents and caregivers of LGBTQIA youth. 6 Topics. 1.5 hours a week to talk and learn. Need support and knowledge? Register below!\n\n Topics include: \n\n1- Basics of Gender and Sexual Identity\n\n2- Body Image and Development of Self Esteem\n\n3- How to Talk to Your LGBTQIA Kids About Sex\n\n4- Helping Your Kids Build a Support Network \n\n5- Coping As Parents","web":"https://forms.gle/PMF12zzE2d8Hok9c6","tel":"","email":"","addr":"","fb":"","ig":""},{"id":"XG6AVndmTUO8j0iKydsJ7g","name":"Human Rights Campaign","cat":"Education/Advocacy","county":"Salt Lake County","counties":["Salt Lake County"],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5fa5e290c79d7b80376e57fa_unnamed.jpg","desc":"Our Mission: By inspiring and engaging individuals and communities, the Human Rights Campaign strives to end discrimination against LGBTQ people and realize a world that achieves fundamental fairness and equality for all. HRC envisions a world where lesbian, gay, bisexual, transgender and queer people are ensured equality and embraced as full members of society at home, at work and in every community.","web":"utah.hrc.org","tel":"202-628-4160","email":"hrcutahvolunteers@gmail.com","addr":"","fb":"https://www.facebook.com/hrc.utah/","ig":"https://www.instagram.com/hrcutah/"},{"id":"OKfOHoTfSiGAlgDpMZKfCg","name":"I'll Walk With You","cat":"Video Project","county":"","counties":[],"demo":["LDS"],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5f5637d9d20ccc0db6248ac1_5f2c881346237b6a67ee1976_I%2527ll%2520Walk%2520With%2520You.jpeg","desc":"These videos were created for Latter-day Saint parents and allies to voice their love for their LGBT brothers and sisters, sons and daughters. They want to give a message of comfort and support to other parents who are navigating the difficult conflicts that can arise in families around this issue. Each video offers a unique perspective, but all of the participants are united in a concern for individuals and families who might be struggling and even suffering because of misunderstandings. The participants are also united in the belief that their LDS religion offers them the tools to resolve these problems in a way that allows for health and growth of each member of the family and preserves the unity and strength of family bonds. Most of these families are also willing to communicate with parents and individuals who are looking for advice and support. If you are new to this issue or if yo","web":"ldswalkwithyou.org","tel":"","email":"","addr":"","fb":"","ig":""},{"id":"O4ddJ23.TSayjrxRmY6xWA","name":"It Gets Better","cat":"Video Project","county":"","counties":[],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5f5637d8c04fcd0094f27b14_5f2d99dcfeb406f686539c20_USGA.jpeg","desc":"In 2012, gay BYU students from the Understanding Same-Gender Attraction (USGA) group created the “It Gets Better” video series in order to promote conversation and understanding for those with same-sex attraction on campus. Kendall Wilcox, a former employee at BYUtv and (at the time) member of the USGA stated “The primary intent [of the video] was to just send a message of love, hope and community to LGBT Mormon youth who are at their most vulnerable, who may be questioning their self-worth and their status before God. . . We want this video to send the message that there is hope, they have a future, there is hope for love and happiness in the future.”","web":"usgabyu.com/it-gets-better","tel":"","email":"","addr":"","fb":"","ig":""},{"id":"2QmWtOiDTaKH5.EN6P6aAA","name":"Journeys of Faith","cat":"Blog","county":"","counties":[],"demo":["LDS"],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5fb495d33c18f3515b791d62_north%20star.jpg","desc":"The Journeys of Faith Project features the personal stories of Latter-day Saint individuals and families addressing gender identity or transgenderism who are striving to find congruence and peace within the context of faith in the gospel of Jesus Christ.\n\nTheir stories allow each of us a glimpse into their inner experience, inviting us into a place of greater awareness and empathy for an aspect of the human experience so personal and poignant to some of our brothers and sisters. As they struggle to address a difficult and complex issue with few answers, and as we walk with them on their personal journeys, they remind us what it means to live by faith.","web":"https://t2m.io/journeys-of-faith","tel":"","email":"","addr":"","fb":"","ig":""},{"id":"VVjJg745R6CCN1.wpEdckQ","name":"Journeys Online Community","cat":"Online Community","county":"","counties":[],"demo":[],"img":"https://hosting.photobucket.com/images/i/lgbtqut/5f663c89dc4ac15aa61147df_novo-logo-afirma_o_n.png","desc":"Affirmation Journeys is a group oriented toward LGBTQIA, their families, and allies who are transitioning out of Mormon orthodoxy, as well as former Mormons. We welcome everybody, but the discussions will be from a perspective of those who are either Mormons undergoing a faith transition, unorthodox Mormons, non-believing Mormons or former Mormons. The group will be open to all topics of particular interest to this community, but it will have a particular goal of helping people move forward in healthy productive ways as they proceed during or following a faith transition.","web":"","tel":"","email":"","addr":"","fb":"https://www.facebook.com/groups/572382942892407/","ig":""},{"id":"6uBFwWk3T7qAy0-5pteinQ","name":"Lesbian Adults Friendship Circle","cat":"Support Circles","county":"Salt Lake County","counties":["Salt Lake County","Utah County","Washington County"],"demo":["Lesbian"],"img":"https://hosting.photobucket.com/images/i/lgbtqut/Encircle_Logo.png","desc":"This friendship circle is for adults (18+) who identify as lesbian. \n\nFriendship Circles?\nThese groups are designed to provide connection with folx you identify with and help you manage the trials you encounter every day. Friendship Circles create an opportunity for you to take control and thrive in your own life.\n\nFriendship Circles provide opportunities for sharing, connection, and support through discussion of issues and experiences relevant to each group, often exploring the intersectionality of conservative cultures, spirituality, sexuality, social issues, transitional issues, and health issues and the ways it impacts us. The groups also provide a great support network—members in similar circumstances with similar feelings with whom they can share in an open and unedited fashion.\n\nGroups organized by sexuality, age, and/or gender identity.\n\nFor schedules and more information please ","web":"","tel":"","email":"","addr":"","fb":"","ig":""},{"id":"JP7DRTkJSGiqIYer096OkA","name":"LGBT Mormon People of Color and Allies Online Community","cat":"Online Community","county":"","counties":[],"demo":["QPOC"],"img":"https://hosting.photobucket.com/images/i/lgbtqut/5f663c89dc4ac15aa61147df_novo-logo-afirma_o_n.png","desc":"The Affirmation: LGBT Mormons, Families, and Friends People of Color and Allies Group is a group of self-identified people of color and allies gathered to explore multiple identities and the intersections of race/ethnicity, sexual orientation, gender identity, and LDS faith.","web":"","tel":"","email":"","addr":"","fb":"https://www.facebook.com/groups/134166980037744/","ig":""},{"id":"c81ITvxyT5-mmeS32NNT4w","name":"LGBTQ & Allied Lawyers of Utah","cat":"Professional Services","county":"","counties":[],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5f5633381f80e62355331c42_5f36a85aa8337617b7ec894a_LGBTQ%2520Allied%2520Lawyers%2520of%2520Utah.png","desc":"LGBT & Allied Lawyers of Utah is a group of lawyers serving lawyers. We are an association of the Utah State Bar and an affiliate of the National LGBT Bar Association. Our mission is to use education and advocacy to promote and support the rights of LGBT people within the legal profession and throughout Utah.We are sometimes contacted by people who are seeking legal advice or looking to hire an attorney who specializes in LGBTQ issues. We have created this directory to assist these potential clients. The attorneys listed below represent clients on LGBTQ issues. While we believe this is an excellent list, we have not verified any of the information they provided. We list every attorney who requests to be added.","web":"https://t2m.io/lgbt-and-allied-lawyers-of-utah","tel":"","email":"","addr":"","fb":"","ig":""},{"id":"rMsGLPWHQUi2OJEvDGLSIQ","name":"LGBTQ Adult Friendship Circle","cat":"Support Circles","county":"Salt Lake County","counties":["Salt Lake County","Utah County","Washington County"],"demo":["LGBTQ Adults"],"img":"https://hosting.photobucket.com/images/i/lgbtqut/Encircle_Logo.png","desc":"This friendship circle is for adults (25+) that identify as LGBTQ+.\n\nFriendship Circles?\nThese groups are designed to provide connection with folx you identify with and help you manage the trials you encounter every day. Friendship Circles create an opportunity for you to take control and thrive in your own life.\n\nFriendship Circles provide opportunities for sharing, connection, and support through discussion of issues and experiences relevant to each group, often exploring the intersectionality of conservative cultures, spirituality, sexuality, social issues, transitional issues, and health issues and the ways it impacts us. The groups also provide a great support network—members in similar circumstances with similar feelings with whom they can share in an open and unedited fashion. \n\nGroups organized by sexuality, age, and/or gender identity.\n\nFor schedules and more information please ","web":"","tel":"","email":"","addr":"","fb":"","ig":""},{"id":"m2kG6ztITCafO6zAT5qX-A","name":"LGBTQ Affirmative Therapist Guild of Utah","cat":"Mental Health/Counseling","county":"","counties":[],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5fbd5b121c01c36c2e81264c_Therapists%20guild.png","desc":"The LGBTQ-Affirmative Psychotherapist Guild of Utah is a Utah-based, grassroots organization of licensed mental-health professionals and students-in-training. We share a collaborative commitment to make affirmative culturally competent therapy available for anyone.The Guild believes that all individuals and families deserve mental health services that affirm sexual and gender diversity. To this end, we provide innovative and affirmative training to mental health professionals and trainees grounded in values of cultural humility, social advocacy, collaboration, and inclusivity. We believe this work honors and celebrates the lived experiences of sexual and gender diverse individuals, families, and communities while promoting justice and dignity.LGBTQ Affirming Therapist DirectoryA directory of self-reported LGBTQ Affirmative therapists in Utah. <a href=\"http://www.lgbtqtherapists.com/direc","web":"https://t2m.io/lgbtq-therapists-guild","tel":"(385) 355-0965","email":"robin@lgbtqtherapists.com","addr":"","fb":"https://www.facebook.com/LGBTQATGU/","ig":""},{"id":"5T.ks.E7Rfq7ZW.4gS5bBQ","name":"LGBTQ and Allies in Wards, Stakes and Missions","cat":"Online Community","county":"","counties":[],"demo":["LDS"],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/612ad970e84a8fdb08668d72_Untitled%20design%20(6).png","desc":"This is a group of active Latter-day Saints (LGBTQ, Allies and Local Leaders) who are working in Ward, Stake, Seminaries and Institutes, Church Schools, or Mission Leadership to put together LGBTQ meetings, firesides, FHEs, materials, class discussions, Church talks, etc.\n\nThe purpose is to share ideas, materials, approaches, events so that each person does not feel they are starting from scratch or alone in their efforts.\nPresident Ballard asked us to council together—and this virtual group gives us a chance to do that—and come up with the right plan/approach for your area of influence.\nIt is not a place to debate Church doctrine or policy.\n\nPosts not focused on this topic will be removed (sorry my friends, but really want to keep the focus on the mission statement).\nYou are welcome to invite others to the group. Remind them to answer the two questions that are required to join the grou","web":"","tel":"","email":"","addr":"","fb":"https://www.facebook.com/groups/1433556613672143","ig":""},{"id":"hfF.2JO2Sv2zJDCh-AJFTw","name":"LGBTQ Youth Friendship Circle","cat":"Support Circles","county":"Salt Lake County","counties":["Salt Lake County","Utah County","Washington County"],"demo":["Youth"],"img":"https://hosting.photobucket.com/images/i/lgbtqut/Encircle_Logo.png","desc":"This friendship circle is for LGBTQ+ youth between the ages of 12-17.\n\nFriendship Circles?\nThese groups are designed to provide connection with folx you identify with and help you manage the trials you encounter every day. Friendship Circles create an opportunity for you to take control and thrive in your own life.\n\nFriendship Circles provide opportunities for sharing, connection, and support through discussion of issues and experiences relevant to each group, often exploring the intersectionality of conservative cultures, spirituality, sexuality, social issues, transitional issues, and health issues and the ways it impacts us. The groups also provide a great support network—members in similar circumstances with similar feelings with whom they can share in an open and unedited fashion.\n\nGroups organized by sexuality, age, and/or gender identity.\n\nFor schedules and more information please","web":"","tel":"","email":"","addr":"","fb":"","ig":""},{"id":"9ag3Ln6RSQ6ssduiLol-MQ","name":"LGBTQ+ Workplace Education Center","cat":"Education/Advocacy","county":"Washington County","counties":["Washington County"],"demo":["Allies"],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/60b40d3855e085624f5b4c33_44395299_349313352496545_6980696748045893632_n.png","desc":"We help you create inclusive spaces where LGBTQ employees can thrive. LGBTQ+ cultural competency training on demand through e-learning courses. Diversity and inclusion training for your entire team has never been easier!","web":"lgbtqworkplace.com","tel":"","email":"info@lgbtqworkplace.com","addr":"","fb":"https://www.facebook.com/lgbtq.education.center/","ig":"https://www.instagram.com/lgbtq_workplace/"},{"id":"Mmh-q5EiRCech3hOFq91Qg","name":"LGBTQIA+ and Allies in Medicine at UUSOM","cat":"College Resources","county":"Salt Lake County","counties":["Salt Lake County"],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/61149051fa744a3212772e2c_BlockU_400px.png","desc":"To increase awareness and education concerning LGBTQIA+ healthcare issues as well as provide a social and support network for University of Utah medical students, health sciences students, residents, and faculty who identify as LGBTQIA+.\nNeed a safe space? Head to the \"Synapse\" in the basement of the Health Sciences Library. This space is designed for students to have a place to go where they can feel comfortable, relax, or study. There are couches, coffee makers, and plenty of study spaces available!","web":"","tel":"","email":"","addr":"","fb":"https://www.facebook.com/groups/154740254907507/","ig":"https://instagram.com/utahallies?igshid=9s4bg39c7s1j"},{"id":"XaaLGelPSlSTQKv9a9AqHQ","name":"Lift + Love","cat":"Resource Page","county":"","counties":[],"demo":["LDS","Parent"],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/60f882f0c3c4dd0ba35e5561_Lift%2BLove.PNG","desc":"My husband, Kenn, and I live in Salt Lake and have three amazing children and a brand-new son-in-law We are a regular LDS LGBTQ family.\n\nAs the mother of an LGBTQ child and a member of the Church of Jesus Christ of Latter-Day Saints, I have learned to rely on the Lord and trust the Inspiration I received. My goal is to keep all of my children connected to their Savior and to teach them to face life with courage and confidence\n\nI learned this growing up in my own LGBTQ family. My oldest brother, Preston was gay. Raising a gay child in the 70s and 80s my parents were on their own to navigate what it meant to be an openly gay family in the church. It was not easy and neither they nor my brother felt supported. But they did the best they could\n\nIn 2017, my brother took his own life. At the same time, my oldest son was starting his own process of coming out. My brother's painful life was a to","web":"liftandlove.org","tel":"","email":"","addr":"","fb":"","ig":"http://instagram.com/liftandloveorg"},{"id":"c8gx2LgFQ0iokHpvKfYbNg","name":"Lift + Love LGBTQ+ Mamas (Parents) Community","cat":"Support Circles","county":"","counties":[],"demo":["Parent"],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/60f882f0c3c4dd0ba35e5561_Lift%2BLove.PNG","desc":"We are excited to have you join this growing group of LDS mothers who want to raise healthy LGBTQ children.  There is wisdom in this community of faithful women and strength in knowing that you are not alone.","web":"liftandlove.org/#/meeting/","tel":"","email":"","addr":"","fb":"","ig":""},{"id":"NBTusl96R.iaVi.yfvTOlw","name":"Living Waters Online Community","cat":"Online Community","county":"","counties":[],"demo":["LDS"],"img":"https://hosting.photobucket.com/images/i/lgbtqut/5f663c89dc4ac15aa61147df_novo-logo-afirma_o_n.png","desc":"Affirmation Journeys is a group oriented toward LGBTQIA, their families, and allies who are transitioning out of Mormon orthodoxy, as well as former Mormons. We welcome everybody, but the discussions will be from a perspective of those who are either Mormons undergoing a faith transition, unorthodox Mormons, non-believing Mormons or former Mormons. The group will be open to all topics of particular interest to this community, but it will have a particular goal of helping people move forward in healthy productive ways as they proceed during or following a faith transition.","web":"","tel":"","email":"","addr":"","fb":"https://www.facebook.com/taliatha.holmes","ig":""},{"id":"RneXZPwrRaysxe2fd3mGVQ","name":"Logan Health Center","cat":"Wellness/Medical","county":"Cache County","counties":["Cache County"],"demo":[],"img":"https://hosting.photobucket.com/images/i/lgbtqut/5f36ad95b2ae3f30b8d8e28b_5f36abc5c9770f898e299192_Planned_20Parenthood.jpeg","desc":"Services Offered:\n\nBirth Control\n\nHIV Services\n\nMen's Health Care\n\nMorning-After Pill (Emergency Contraception)\n\nPregnancy Testing & Services\n\nPrimary Care\n\nSTD Testing, Treatment, & Vaccines\n\nWomen's Health Care\n\nAbortion Referrals\n\nFor more information, hours, and to book online, please visit the Health Center Website.","web":"","tel":"","email":"","addr":"550 N Main #17 Logan, UT 84321","fb":"","ig":""},{"id":"J3ZoWtatSG6B7sm0Qy0xiQ","name":"Logan Pride","cat":"Pride Center","county":"Cache County","counties":["Cache County"],"demo":["Age 18 and up."],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5f5633d794cb9119b3671eae_5f36a981be85343e64aea29d_Logan%2520Pride.png","desc":"Logan Pride strengthens, serves, and advocates for the Cache Valley LGBTQ community, including individuals, their families, and allies. We strive to bring our communities together in equality and love.","web":"https://www.loganpride.org/","tel":"","email":"info@loganpride.org","addr":"69 E 100 N, Logan, UT 84321","fb":"https://www.facebook.com/loganprideUT/","ig":"https://www.instagram.com/loganprideut/"},{"id":"lz.EUHppSQ6juJvyT-RAqQ","name":"Love And Lift Inspirational Sunday","cat":"FHE/Sunday Service","county":"Salt Lake County","counties":["Salt Lake County"],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/60f7a10284ee1c4841b27f47_81678267_10221067264009177_4643021326724890624_n.jpg","desc":"A place to be uplifted by others who walk the same road. This group represents those from different religions and faiths. Some are still in the LDS faith and some are completely out. We even have some who are agnostic but still want to feel uplifted and have a place to share their voice and feelings.\n\nFor more information and access please contact Jordan via Facebook below.","web":"","tel":"","email":"","addr":"","fb":"https://www.facebook.com/MusicFan7737","ig":"https://instagram.com/lgbtqsundayschool?utm_medium=copy_link"},{"id":"WukG5owtTUCU45NUOac7QQ","name":"Mama Dragons","cat":"Support Organization","county":"","counties":[],"demo":["Parent"],"img":"https://hosting.photobucket.com/images/i/lgbtqut/file.png","desc":"About Us: Mama Dragons is a support organization for Mormon and former-Mormon mothers of LGBTQ children. Mama Dragons exist to inspire and empower mothers. We actively promote healthy, loving, and supportive environments for mothers of LGBTQIA children.Our Mission: We support, educate, and empower mothers of LGBTQ children.","web":"http://Mamadragons.org","tel":"","email":"info@mamadragons.org","addr":"","fb":"https://www.facebook.com/mamadragons/","ig":"https://www.instagram.com/themamadragons/?hl=en"},{"id":"2fUnN1.NSieg8xTa-oMDrw","name":"Mama Dragons Facebook Group","cat":"Online Community","county":"","counties":[],"demo":["Parent"],"img":"https://hosting.photobucket.com/images/i/lgbtqut/file.png","desc":"This Mama Dragons Main Group on Facebook is the primary support group for all mothers of LGBTQ children navigating this sometimes challenging journey within their family and community. This group strives to be a space free of judgment between members and one that creates a safe place for conversation and support for individuals regardless of cultural or religious backgrounds. Mamas can ask questions, share success stories, share heartaches and heartbreaks, request and give advice, and bring a wealth of knowledge and experience to others in the group.\n\nFor more targeted needs and discussions, Mama Dragons also offers Facebook subgroups. Once you are a member of this main support group (or the Madres Dragones Facebook group), you can be invited – or request an invitation – to join other Mama Dragons subgroups listed below that meet your needs.","web":"","tel":"","email":"","addr":"","fb":"facebook.com/groups/953372108027028","ig":""},{"id":"a.YwfdysdTv6cEi9YtPsqYA","name":"Men Finding Peace - Salt Lake City","cat":"Support Circles","county":"Salt Lake County","counties":["Salt Lake County"],"demo":["Gay Men"],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5fb49c263c18f396ea792537_mfpslc.jpg","desc":"What is Men Finding Peace?\n\nMore than a support group, more than a church meeting, Men Finding Peace is a group of men who share common goals and needs.  It is a place where men can be authentic and learn from other gay/SSA men from our everyday experiences, faith, and insight. To give strength to those who strive to live a covenant life of faith or those men who are just seeking peace and acceptance wherever they may be on their journey. It’s a place where ideas are shared to find strength, hope, and resolve with like men who share a common bond in brotherhood. A group that provides fellowship, purpose, and meaning through group sharing and other activities. \n\nThe Men Finding Peace group meets every Wednesday at 7:00 pm until 8:30 pm. *Note current meetup information available on the Men Finding Peace Salt Lake City Facebook Group. \n\n*Disclaimer*: Men Finding Peace is an independent gro","web":"menfindingpeace.blogspot.com","tel":"","email":"","addr":"","fb":"http://www.facebook.com/groups/1038606652939212/","ig":""},{"id":"2Y7BD9v-Q4yf6p5Yx8usjQ","name":"Men Finding Peace - Utah Valley","cat":"Support Circles","county":"Utah County","counties":["Utah County"],"demo":["Gay Men"],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5fb49cabb50ea69dde81ea0c_mfpuv.jpg","desc":"More than a support group or a church meeting, “Men Finding Peace” is an independent group of men who share common goals, needs, and who want to participate in a gospel-oriented and positive association. It serves as a forum where men can learn from each other what it means to experience SSA and simultaneously live a covenant life of faith and hope within the bounds the Lord has set. It is a place to learn how others have found strength, resolve, and peace within themselves, their families, and other men who share a common bond in brotherhood.In this sense, Men Finding Peace accepts and adopts the mission of North Star International* to empower individuals and families, addressing sexual orientation or gender identity issues, to genuinely and joyfully live the Gospel of Jesus Christ, and to keep sacred covenants.We recognize that SSA is a complex subject often causing great inner conflic","web":"mfpuv.wordpress.com","tel":"","email":"menfindingpeaceuv@gmail.com","addr":"","fb":"","ig":""},{"id":"S-6EPflFQKG2aei2KYi9fQ","name":"Millennials Online Community","cat":"Online Community","county":"","counties":[],"demo":[],"img":"https://hosting.photobucket.com/images/i/lgbtqut/5f663c89dc4ac15aa61147df_novo-logo-afirma_o_n.png","desc":"This group is for individuals who were born 1980-2000. This group is meant to be a safe space that affirms each individual's sexuality, faith or lack of faith. This is a space for compassionate support and fellowship of all LGBTQ and allied people with an LDS background. This space is also used to provide ideas and information about events, socials, and other programming that would be effective for LGBTQ Mormons, their families, friends, and church leaders. No matter the personal path you are on if you believe in Affirmation and it's future, this is the right group for you.","web":"","tel":"","email":"","addr":"","fb":"https://www.facebook.com/groups/affirmationmillennials","ig":""},{"id":"2zCsEegaSsyRuWIscMN8DA","name":"Mixed Orientation Families Online Community","cat":"Online Community","county":"","counties":[],"demo":["Mixed Orientation"],"img":"https://hosting.photobucket.com/images/i/lgbtqut/5f663c89dc4ac15aa61147df_novo-logo-afirma_o_n.png","desc":"An online community by Affirmation. For families impacted by Mixed Orientation Marriage (MOM). This group invites married MOM couples, as well as both gay, straight, and bisexual ex-spouses to join.To join please connect with Ron Raynes via Facebook below:","web":"","tel":"","email":"","addr":"","fb":"https://www.facebook.com/ron.raynes.1","ig":""},{"id":"PxX9ghZDRZ2Ij9IO4Skdtw","name":"Mormon and Gay Subreddit","cat":"Online Community","county":"","counties":[],"demo":["LDS"],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/611490ab8fac2daf3bde33ec_communityIcon_ndkyxb5uwyb61.jpg","desc":"This is a subreddit where LGBTQ+ members of The Church of Jesus Christ of Latter Day Saints (or past members, or anyone else) can talk about their experiences being LGBTQ+. A place to promote discussions, have fun, ask questions, make friends, and find resources. You are not in this alone!","web":"reddit.com/r/MormonandGay","tel":"","email":"","addr":"","fb":"","ig":""},{"id":"PRCT24nnQoi3Rj8KukanLw","name":"National Center for Transgender Equality ID, Docs, and Name Change Guide","cat":"Name/Gender Change Assistance","county":"","counties":[],"demo":["Trans"],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/611490d1d07df429168408d4_yo3Cw5wy_400x400.jpg","desc":"Welcome to our one-stop hub for name and gender change information. Find out how to update your name and gender on state and federal IDs and records.","web":"https://transequality.org/documents/state/utah","tel":"(202) 642-4542","email":"","addr":"","fb":"https://www.facebook.com/transequalitynow","ig":""},{"id":"rx04NVBAQNmfJaObTvj3bQ","name":"North Star Online Gender Incongruence Group","cat":"Online Community","county":"","counties":[],"demo":["Trans"],"img":"https://hosting.photobucket.com/images/i/lgbtqut/5fb495d33c18f3515b791d62_north_star.jpg","desc":"This group is for individuals, ages 18+, who experience gender dysphoria as well as their spouses, family members and friends.","web":"https://t2m.io/north-star-gender-incongruence","tel":"","email":"","addr":"","fb":"","ig":""},{"id":"CBvYMCWDTb6ONIE4oMdLTg","name":"North Star Online Parents and Family","cat":"Online Community","county":"","counties":[],"demo":["Parent"],"img":"https://hosting.photobucket.com/images/i/lgbtqut/5fb495d33c18f3515b791d62_north_star.jpg","desc":"For parents, siblings, or other family members, ages 18+, to provide an open and supportive forum to encourage, strengthen, and educate one another, and to learn how to best encourage, strengthen, build up and support loved ones who experience same-sex attraction or gender dysphoria.","web":"northstarlds.org/join-facebook-parents-family","tel":"","email":"","addr":"","fb":"","ig":""},{"id":"Z8BWgN5nSLW6VCKX41q-vw","name":"North Star Online Youth Group","cat":"Online Community","county":"","counties":[],"demo":["Youth","LDS"],"img":"https://hosting.photobucket.com/images/i/lgbtqut/5fb495d33c18f3515b791d62_north_star.jpg","desc":"This group is for youth, ages 13-17 (male and female), who experience either same-sex attraction or gender dysphoria (transgenderism.) As well as young men and women of similar age who do not experience SSA or gender dysphoria whose sole motivation is to give support or increase in understanding.\n\nTo join click the link below.","web":"https://t2m.io/north-star-youth-facebook","tel":"","email":"","addr":"","fb":"","ig":""},{"id":"oDtpVM00QsyFq5h1F.2ohQ","name":"Now Playing Utah","cat":"Publications/Media","county":"Salt Lake County","counties":["Salt Lake County"],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/6114912ad07df458b9840aa0_NPU-logo-2020a.png","desc":"The mission of NowPlayingUtah is to increase awareness about arts and cultural opportunities in Utah by providing a comprehensive events resource. NowPlayingUtah has a database of LGBTQ+ positive arts and cultural opportunities in Utah.","web":"https://t2m.io/now-playing-lgbtq","tel":"","email":"","addr":"","fb":"","ig":""},{"id":"xdJX9JGLQSGv4of3JovwNw","name":"Ogden Health Center","cat":"Wellness/Medical","county":"Weber County","counties":["Weber County"],"demo":[],"img":"https://hosting.photobucket.com/images/i/lgbtqut/5f36ad95b2ae3f30b8d8e28b_5f36abc5c9770f898e299192_Planned_20Parenthood.jpeg","desc":"Services Offered:\n\nBirth Control\n\nHIV Services\n\nMen's Health Care\n\nMorning-After Pill (Emergency Contraception)\n\nPregnancy Testing & Services\n\nPrimary Care\n\nSTD Testing, Treatment, & Vaccines\n\nWomen's Health Care\n\nAbortion Referrals\n\nFor more information, hours, and to book online, please visit the Health Center Website.","web":"","tel":"","email":"","addr":"4387 Harrison Blvd. Ogden, UT 84403","fb":"","ig":""},{"id":"POgh81.-QtO3Onj6sDP.zA","name":"Ogden Pride","cat":"Pride Center","county":"Weber County","counties":["Weber County"],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5fb54d2aaf5bae6788c74a9b_Ogden%20Pride.jpg","desc":"Our Mission: Ogden Pride celebrates and supports the LGBT community, individuals and their families and allies in Northern Utah in building and strengthening inclusive communities. We are committed to excellence in advocacy, educational programs and services.","web":"ogdenpride.org","tel":"","email":"","addr":"","fb":"https://www.facebook.com/OgdenPrideInc/","ig":""},{"id":"Pb.hKaQ-R2GlAlSr05tozA","name":"OkaySo","cat":"Medical and Wellness","county":"","counties":[],"demo":[],"img":"https://storage.googleapis.com/glide-prod.appspot.com/uploads-v2/GLyS34gJTOtHtpGe05Cl/pub/O3HFt6VCJO79Hn9UzBEH.png","desc":"","web":"","tel":"","email":"","addr":"","fb":"","ig":""},{"id":"JGGBADz6TGqimUS4sXDwfQ","name":"On the Record | A Chronology of LGBTQ+ Messaging","cat":"Publications/Media","county":"","counties":[],"demo":["LDS"],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5f5631ab2220c976a31841d1_5f2c3bdfa932cb1decb0e7e3_cbbea37f.jpeg","desc":"On the Record, an interactive PDF document, is intended to establish a historical accounting of the official statements provided by The Church of Jesus Christ of Latter-day Saints through the Church’s education, policy, disclosure, and messaging regarding LGBTQ+ topics.","web":"lattergaystories.org/record","tel":"","email":"","addr":"","fb":"","ig":""},{"id":"OadsO.TxR4-HOZ4VrIKXeA","name":"Online Parent Support Group","cat":"Online Community","county":"","counties":[],"demo":["Parent"],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5f2c881346237b6a67ee1976_I%27ll%20Walk%20With%20You.jpg","desc":"Welcome to the I'll Walk With You Facebook group for LDS parents of LGBT children. This group is to provide support for LDS parents who want to stay active in the church while supporting their LGBT children or family members. We hope you find support for yourself and give support to others here.","web":"","tel":"","email":"","addr":"","fb":"https://www.facebook.com/groups/WalkWithYouLDSParentsOfLGBTQ/?fref=nf","ig":""},{"id":"UgIAWXyvTs2LuuX-3se1NQ","name":"Parents and Caregivers Support Group","cat":"Support Circles","county":"Salt Lake County","counties":["Salt Lake County"],"demo":["Parent"],"img":"https://hosting.photobucket.com/images/i/lgbtqut/Logo_-_square.jpg","desc":"PCSG is a peer-led support group that meets weekly on Thursdays from 6:00-7:30. It is open to all parents and caregivers of LGBTQ+ youth.","web":"https://www.utahpridecenter.org/youth-programs/y-parent-caregiver-sg","tel":"801-539-8800","email":"youth@utahpridecenter.org","addr":"1380 South Main, SLC, UT, 84115","fb":"","ig":""},{"id":"hwX0r3DCRx-YohwT-j6JDQ","name":"Parents Support Group","cat":"Support Circles","county":"Cache County","counties":["Cache County"],"demo":["Parent"],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5f358fc72b040487de0d14ba_Cache%20Pride.jpg","desc":"Our Parent group is open to all parents of and those in care of LGBTQIAP+ youth or are LGBTQIAP+ parents of youth. This group ordinarily meets as time permits. Parents work hard to take care of their children and this group will give parents an opportunity to socialize, give/receive information, advice, emotional, and moral support. Families have an opportunity to benefit from the unique connection that exists amongst families of children &amp; youth who are LGBTQIAP+ and may experience mental health challenges. Also, be on the lookout for family events and community nights.Located at 596 E 900 N, Logan, UT 84321","web":"cachepridecenter.org","tel":"(435) 363-5473","email":"","addr":"","fb":"https://www.facebook.com/CachePrideCenter/","ig":""},{"id":"F19iMQpUQFGWVawPQES5vQ","name":"Pathways Real Life Recovery","cat":"Mental Health/Counseling","county":"Salt Lake County","counties":["Salt Lake County"],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/6114914ff9a74f16afeb892c_Pathways.png","desc":"Pathways Real Life Recovery understands the numerous challenges that the LGBTQ+ community go through living in a heteronormative world, and it be even more challenging in the super-conservative state of Utah. Many gay people clash with loved ones due to their identity, and even years later the pain can linger. Sometimes, it’s a close friend or family cutting off all ties, or in other times, it’s bitter words and vitriol spewed in the heat of the moment that can't be forgotten.\n\nRegardless if you seek therapy for issues related to your LGBT status or not, it is imperative you feel supported and able to speak freely in order to benefit from the therapeutic experience. This is especially true for those confronted with the double stigma of mental health issues and LGBT orientation. Pathways is an LGBT counselor in Utah for teens and adults who are seeking professional counseling. We can help","web":"https://pathwaysreallife.com/lgbtq-counselor-in-utah/","tel":"801-895-3006","email":"info@pathwaysreallife.com","addr":"8706 S 700 E #205, Sandy, UT 84070","fb":"https://www.facebook.com/PathwaysRealLifeRecovery","ig":"https://www.instagram.com/pathwaysrealliferecovery/"},{"id":"OoBxKQKhRe6Eh5Gpo4Tgwg","name":"Peculiar - Allies and Appetizers","cat":"Speaker Series","county":"Salt Lake County","counties":["Salt Lake County"],"demo":["Parent"],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/60b4129762daab36ec2515f5_Peculiar.png","desc":"Mission Statement: To create safe spaces, filled with great conversation and a new understanding of how to better love and respect our LGBTQ+ family.","web":"https://www.thepeculiar.org/allies-and-appetizers","tel":"(801) 628-8509","email":"","addr":"","fb":"https://www.facebook.com/thepeculiarorg","ig":""},{"id":"eEcoTbtXTbKRn.A9W.Eqqg","name":"Peculiar Journal","cat":"Publications/Media","county":"Utah County","counties":["Utah County"],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/6114919a500330dbad459bde_Peculiar%20Journal.PNG","desc":"Peculiar is a queer literary journal showcasing prose, poetry, art, and photography. With our roots in the Mormon stronghold of Provo, Utah, peculiar began as a way to recognize the creative talents of the often-overlooked queer community within Utah’s unique culture. As our journal has grown over the past few years—and our staff has begun setting roots nationwide—we’ve decided to broaden the scope of peculiar to include queer voices from anywhere and everywhere. No matter how far you are or how quietly you whisper, know that we hear you.\n​\n​In our first issue, co-editor-in-chief Aaron Gates wrote the following in his foreword: “To belong, isn't that what we are fighting for, constantly? Every day a wave surges against us, telling us we are too different, telling us we have no place, telling us that something is wrong with us. No one can tell you what you are worth; that is for you to de","web":"peculiarjournal.com","tel":"801-891-9618","email":"peculiarjournal@gmail.com","addr":"145 E Center St #2A Provo, UT 84606","fb":"https://www.facebook.com/peculiarjournal/","ig":"https://instagram.com/peculiarjournal?igshid=yvlxg1m8eipq"},{"id":"BOV6Uv1hRNeGvOMhvOWJ7g","name":"Peculiar Stories","cat":"Video Project","county":"","counties":[],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/60b4129762daab36ec2515f5_Peculiar.png","desc":"Peculiar Stories is an opportunity to share your personal stories and/or insight on your experiences as a member of the LGBTQ+ community. Our community is strengthened as a whole when we share these stories. These stories are intended to bring awareness, change, and ultimately save the lives of our LGBTQ+ youth and community. We are grateful for the courage and the vulnerability shown here as well as the example given. Please honor these stories. They are sacred.","web":"https://www.thepeculiar.org/peculiar-stories","tel":"","email":"","addr":"","fb":"","ig":""},{"id":"B-NaH5McQcKW7bpKXmkvnQ","name":"Planned Parenthood Association of Utah","cat":"Wellness/Medical","county":"","counties":[],"demo":[],"img":"https://hosting.photobucket.com/images/i/lgbtqut/5f36ad95b2ae3f30b8d8e28b_5f36abc5c9770f898e299192_Planned_20Parenthood.jpeg","desc":"Planned Parenthood Association of Utah shares the vision of an equitable world articulated by the Planned Parenthood Federation of America: where sexual and reproductive rights are basic human rights, where access to health care doesn't depend on who you are and where you live, and where every person has the opportunity to choose their own path to a healthy and meaningful life. Our mission is to empower Utahns of all ages to make informed choices about their sexual health, to ensure access to affordable, quality health care and education, and protect their right to do so.","web":"plannedparenthood.org/planned-parenthood-utah","tel":"","email":"","addr":"","fb":"","ig":""},{"id":"H6i3fbAySKKf6qQ8gcEWFQ","name":"Pre-Teen Support Group","cat":"Support Circles","county":"Cache County","counties":["Cache County"],"demo":["Youth"],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5f358fc72b040487de0d14ba_Cache%20Pride.jpg","desc":"Our Preteen Group is open to all LGBTQ+ and LGBTQ+ affirming youth ages 10-14. We give our preteens a monitored platform to communicate with each other throughout the week and a fixed opportunity to reach out for mutual support from their peers. This allows our preteens to communicate and build a bond with each other, as well as CPC volunteers, for ongoing support and a sense of belonging outside of our Tuesday night group.","web":"cachepridecenter.org","tel":"435-363-5473","email":"cachepridecenter@gmail.com","addr":"","fb":"https://www.facebook.com/CachePrideCenter/","ig":""},{"id":"3hxLOeqvR7C1WCaD9-Wfsw","name":"Prepare Online Community","cat":"Online Community","county":"","counties":[],"demo":["LDS"],"img":"https://hosting.photobucket.com/images/i/lgbtqut/5f663c89dc4ac15aa61147df_novo-logo-afirma_o_n.png","desc":"This group provides fellowship for LGBTQ people who desire to attend the LDS church and are supportive of everyone whether they're in a same-sex relationship, an opposite-sex relationship, or celibate/abstinent.","web":"","tel":"","email":"","addr":"","fb":"https://www.facebook.com/groups/TheLordWillPrepare/","ig":""},{"id":"jJOvLyLgTGiosc3ALjCGww","name":"Pride of Southern Utah","cat":"Pride Center","county":"Washington County","counties":["Washington County"],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/611491d80dac646a9ddf7c79_Southern%20utah.png","desc":"Together we can make a change.\n\nPride of Southern Utah is a grass roots grown non-profit group of who wants to see a change. A change of attitude, acceptance, perspective and love within and surrounding the LGBTQ+ community. Pride of Southern Utah has partnered with A.R.T.S. Inc. as our fiscal partner which gives us non-profit status. Every Dollar, every cent for that matter goes back into the festival and the LGBTQ+ community. While we might be small, we are big in heart, determination and might. Together we can make a change. But we need your help. Whether you are a vendor, volunteer, entertainer or a sponsor we hope that you will join us. Thank you for time and care. \n\nWho we are: Pride of Southern Utah is a non-profit organization founded on the belief that everyone belongs. Whether you are a member of the LGBTQ+ community or one of our Allies, we want to serve you.   \n\nPhilosophy: B","web":"https://www.prideofsouthernutah.org/","tel":"","email":"","addr":"307 North Main Street, St. George, UT, 84770","fb":"https://www.facebook.com/DiscoverPride/","ig":""},{"id":"AChbgTB1R2yLdMSfPVLGWw","name":"Progressive Paths Therapy","cat":"Mental Health/Counseling","county":"Utah County","counties":["Utah County"],"demo":["Adults"],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/6176016f3d9c192bef6c6e3d_Untitled%20design%20(21).png","desc":"Welcome to Progressive Paths Therapy! Does it feel like you can’t control your anxiety no matter how hard you try?\n\nAre you feeling hopeless, isolated and not your usual self?\n\nAre you going through a faith crisis, shift, or transition?\n\nDoes it feel like your marriage/couple relationship is breaking down?\n\nAre you seeking for a healthier, closer family relationship?\n\nAre you struggling with problematic or out of control sexual behavior?\n\nHave you tried to solve the problems in your life on your own and realized you need help from someone else?\n\nIf you answered yes to any of these questions, then you have made the right choice by being here.\n\nAnd we know this is hard. You've likely been debating seeking help for months, if not years. But we are so glad you found us and have taken the courageous step of being here.","web":"progressivepathstherapy.com","tel":"801-704-5066","email":"info@progressivepathstherapy.com","addr":"1175 South 800 East, 2nd floor Orem UT 84097","fb":"","ig":""},{"id":"gVxtobVtQRWufksvAEX13g","name":"Project Rainbow","cat":"Community Projects","county":"Salt Lake County","counties":["Salt Lake County","Davis County","Weber County"],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/6114921ddd8c32233dbb123a_101018466_969989456790318_6204034070993698816_n.png","desc":"Project Rainbow works to promote LGBTQ+ visibility throughout Utah and foster inclusivity in every corner of the state.\n\nFlag Campaigns\n\nProject Rainbow’s largest fundraiser is our flag campaigns. We stake flags in front of thousands of homes and businesses across Utah each year to celebrate the various pride festivals and events that take place throughout the State. \n\nCommunity Fund\n\nThe Project Rainbow Community Fund helps finance events or projects that align with our mission to “promote LGBTQ+ visibility throughout Utah.” Individuals, groups, and organizations can apply for grants ranging from $100-$7,000.\n\nTransgender Day of Remembrance\n\nFor the week of Transgender Day of Remembrance (November 20) Project Rainbow stakes transgender pride flags along the Wasatch front from Ogden to Provo. Transgender Day of Remembrance (TDOR) is a day to increase visibility for the transgender commun","web":"projectrainbowutah.org","tel":"801-688-3275","email":"lucas@projectrainbowutah.org","addr":"","fb":"http://www.facebook.com/projectrainbowutah","ig":"http://instagram.com/projectrainbowutah"},{"id":"fJF9SttGTuehAGkbOhsjng","name":"Provo Pride","cat":"Pride Center","county":"Utah County","counties":["Utah County"],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5fbd57ccc2d6fb05e3e7dbca_Provo%20Pride%20(1).jpg","desc":"We are the Provo Pride Council, a non-profit corporation organized to act as a community resource and symbol of hope and pride for residents of Utah County who may identify as gay, lesbian, bisexual, pansexual, transgender, transsexual, queer, questioning, intersex, intergender, asexual, etc. (abbreviated as LGBTQ or LGBT for simplicity).MISSIONOur mission is to support and celebrate the LGBTQ community in Provo and Utah County and foster understanding and ties with the larger community through a Pride Festival and other outreach programs. We affirm the equality, dignity, and right to self-determination of all people.VISIONWe aim to improve our support for the LGBTQ and ally community in Utah County by expanding our outreach programs, holding a Pride Parade in addition to the Festival, building an LGBTQ Center, providing help for the homeless youth population and preventing more homeless","web":"provopride.org","tel":"","email":"","addr":"","fb":"https://www.facebook.com/ProvoPride/","ig":"https://www.instagram.com/provopride/?hl=en"},{"id":"Y6Goh0bBTF6vptUGvuGJMw","name":"Q Pages","cat":"Publications/Media","county":"Salt Lake County","counties":["Salt Lake County"],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/6114924ffa744a5ce7773490_10500579_797248366972508_8796192887282199012_n.jpg","desc":"Welcome to the Q Pages, Utah’s businesses and services friendly to the gay, lesbian, bisexual, transgender and ally community. These companies have specifically chosen to market their availability to the LGBT community and have signed a pledge that they and their employees will treat us with dignity, respect, and fairness.","web":"https://www.qpages.com/","tel":"801-997-9763","email":"","addr":"222 S Main St, Ste 500 Salt Lake City UT 84101","fb":"https://www.facebook.com/QPagesUtah","ig":""},{"id":"a-KtaHaNqQyKXUJ-MdtBq.Q","name":"QTalks","cat":"Speaker Series","county":"Salt Lake County","counties":["Salt Lake County"],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5fb96adfcdd292cdcc7806c5_Equality%20utah.png","desc":"QTalks is a quarterly queer lecture series provided by the Equality Utah Foundation. Past guest speakers have included Dustin Lance Black, Samantha Allen, and more.","web":"equalityutah.org/qtalks","tel":"","email":"","addr":"","fb":"","ig":""},{"id":"bcyBXVGES-STi-sUdfqiBw","name":"QUAC - Queer Utah Aquatics Club","cat":"Social Groups","county":"Salt Lake County","counties":["Salt Lake County"],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5f5634b6bf3eb9120c24b690_5f36b0880c5d7cd59e54b4ac_Quac.png","desc":"Queer Utah Aquatic Club, Inc. ( QUAC) is a 501(c)(3) non-profit organization dedicated to the promotion of adult, amateur swimming regardless of age, ability, gender identity, or sexual orientation. QUAC is the largest LGBTS sports club in Utah. QUAC offers swimmers and water polo players of all abilities a supportive and safe environment to improve their skills, get some exercise, meet people with similar interests and, if they so choose, the opportunity to compete. Whether you are interested in swimming, multi-sports, or water polo; whether you’re a former competitor or can barely doggy paddle, QUAC has something to offer. Come join us at practice and get involved with one of the biggest and friendliest sports groups in Utah! QUAC is also a Learn to Swim Program in cooperation and with grants from USMS ​Swimming Saves Lives Foundation.","web":"https://www.quacquac.org/","tel":"","email":"info@quacquac.org","addr":"Fairmont Aquatic Center, 1044 East Sugarmont Drive, Salt Lake City, UT 84106","fb":"https://www.facebook.com/quacquac","ig":"https://www.instagram.com/quac_aquatics/"},{"id":"6KBmHqUSRYWJFPYdWstM-g","name":"Queer Community Allies","cat":"Education/Advocacy","county":"Utah County","counties":["Utah County"],"demo":["Youth"],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/6114926aa2c30956464cf12f_QCA.jpg","desc":"Local GSA Support\nWe support GSAs (gay straight alliances/gender sexuality alliances; student-led with a teacher-staff-counselor advisor) in local high schools. Posters, stickers, flags, buttons, masks, wrapped snacks, books, funds for supplies, crafting items, board games, cards, guest visits from affirming adults, contacts from local businesses who can partner for donations… If they don't have the resources for success, we try to help.\n\nClassroom Decor & Educator Supplies\nTeachers often ask us for buttons to distribute to faculty-friends and students and for posters, stickers and flags for their classrooms. If you’re a teacher who would like some items, reach out! We’d be happy to gift you some!\n\nCommunity Events\nWe love going to Pride, joining other organizations at various city community nights, being involved with other local youth efforts, and hosting events to talk with educators ","web":"queercommunityallies.org","tel":"","email":"contact@queercommunityallies.org","addr":"","fb":"https://www.facebook.com/QueerCommunityAllies/","ig":"https://www.instagram.com/queercommunityallies/"},{"id":"Z8LBm637S.SleHlW3kZxCg","name":"Queer Friends","cat":"Social Groups","county":"Salt Lake County","counties":["Salt Lake County"],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5f5634b4418da6b96c057ca7_5f36b0f42f3ef9bbbfebab19_Queer%2520Friends.png","desc":"Queer Friends: queer is normal. We are an all-inclusive social group of LGBTQIA+ friends having a great time in Salt Lake! This group is open to any gender-identity, sexual orientation, monogamous and non-monogamous relationships AND queer-friendly allies. Singles, couples, friends and family are all welcome as long as they are queer-friendly. Our goal is to also create a safe, welcoming and supportive community. We especially welcome people who are questioning their identity and just starting the \"coming out\" process.<h2>Mission</h2><p>To create a safe, welcoming, and supportive all-inclusive community through normal social activities and education.</p><h2>Vision</h2>We envision a community of queer people and allies working together to create a culture of love, acceptance and nondiscrimination so all queer people can be true to themselves.We host a broad range of events using the Meetu","web":"queerfriends.org","tel":"","email":"","addr":"","fb":"","ig":""},{"id":"5hhHWAjISdSUNBwBqvMwvg","name":"Queer Meals","cat":"Community Projects","county":"Utah County","counties":["Utah County"],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5f563d75e654801c2fec8991_5f36b04e5ad1bd42dc635fbb_cropped-QueerMeals_doodles_web-02%2520(1).png","desc":"Providing meals, groceries, love, and the occasional pizza. Life in Provo can be overwhelming for the LGBTQ community. Because of this, there are many groups in Provo that serve the LGBTQ community. QueerMeals is simply one more. We are open 24/7 to folks who need a safe space to sit, visit and decompress—where their pronouns will be respected and their individual paths will be cherished. We have extensive experience with suicide prevention counseling and visitors can expect to feel validated and appreciated. If you need to come over, or even if you do not want to leave your home but you would like a visit or a meal, send us a message and we’ll tell you how to find us.","web":"http://QueerMeals.com","tel":"","email":"","addr":"","fb":"","ig":""},{"id":"TzoFxQ7nRISXtvF5MhuZPw","name":"Queer Mormon Therapists","cat":"Other","county":"","counties":[],"demo":[],"img":"https://storage.googleapis.com/glide-prod.appspot.com/uploads-v2/NSfaaNV0fRhAK9yZqEUi/pub/6NVq18WZh85gz6ou74eX.png","desc":"","web":"","tel":"","email":"","addr":"","fb":"","ig":""},{"id":"V.RXFCIcSVmfTlxhWXPJCw","name":"Queer Spectra","cat":"Publications/Media","county":"Salt Lake County","counties":["Salt Lake County"],"demo":[],"img":"https://storage.googleapis.com/glide-prod.appspot.com/uploads-v2/NSfaaNV0fRhAK9yZqEUi/pub/3My94t7vhOSkQlhcLa9z.jpg","desc":"A safe space for artists who self-identify as LGBTQIA+ to showcase their works and engage audiences in conversation regarding art and queer identity.\n\nOur Mission\n\nQueer Spectra Arts Festival is dedicated to showcasing arts from multiple LGBTQIA+ perspectives. \nAs curators, we aim to present a diverse array of voices, backgrounds, experiences, cultures, mediums, and artistic disciplines in order to celebrate queer artistic expressions. Queer Spectra Arts Festival challenges and contributes to contemporary understanding of queer discourse while promoting nuanced conversations between artists and audiences about queer identity and art.","web":"https://www.queerspectra.com/","tel":"","email":"queerspectra@gmail.com","addr":"","fb":"https://www.facebook.com/Queer-Spectra-Arts-Festival-422526101851501/?modal=admin_todo_tour","ig":"http://instagram.com/queerspectra"},{"id":"UsNLPOJNQG-I8nWHP12L3Q","name":"Radical Adventure Riders SLC Chapter","cat":"Social Groups","county":"Salt Lake County","counties":["Salt Lake County"],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/61731f738b5a81f47a7b8f87_151191169_636978377083881_6564652702243824200_n.jpg","desc":"RAR creates networks and programs to support femme, transgender, woman, and non-binary (FTWN-B) and Black, Indigenous, People of Color (BIPOC) in the cycling and outdoors scene.","web":"https://radicaladventureriders.com/chapters/salt-lake","tel":"","email":"rar.saltlake@gmail.com","addr":"","fb":"https://www.facebook.com/radical.adventure.riders","ig":"https://instagram.com/rar.saltlake"},{"id":"rOpcLkapTpWh61bC45v0FQ","name":"RaYnbow Collective","cat":"College Resources","county":"Utah County","counties":["Utah County"],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/61d91f2f0d3d6d3eda28f567_Untitled%20design%20(44).png","desc":"The RaYnbow Collective is a volunteer organization located in Provo, Utah, focused on creating and identifying safe spaces for LGBTQ+ students, faculty, and staff at Brigham Young University. To accomplish this, we develop networks across Utah with organizations, businesses, artists, and activists to support BYU students wherever they are physically, emotionally, and spiritually.","web":"linktr.ee/raynbow.collective","tel":"","email":"raynbow.collective@gmail.com","addr":"","fb":"","ig":"instagram.com/raynbow.collective"},{"id":"fxvTgp2YQ8-.mD.Fyc0uZQ","name":"Rebirth OB/GYN","cat":"Wellness/Medical","county":"Salt Lake County","counties":["Salt Lake County"],"demo":["Trans"],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/611b35386e7390ec22a2ec1a_Rebirth.jpg","desc":"Rebirth OBGYN is a Gender Center & OBGYN Clinic located in Salt Lake City, UT\n\nDue to stigma and lack of knowledge, transgender individuals may not get the quality health care they need or deserve. Rixt Luikenaar, MD, FACOG, at Rebirth OB/GYN in Salt Lake City specializes in transgender health and manages both primary care and the specialized medical needs for transgender and gender-nonconforming individuals. To schedule an appointment, call the office today or book online.","web":"rebirthobgyn.com","tel":"801-272-3909","email":"","addr":"2180 E. 4500 S., Suite 270, Salt Lake City, UT 84117","fb":"","ig":""},{"id":"HZ-GSWvnSI2bBiMQUn-B.Q","name":"Safe Space UT","cat":"Community Projects","county":"Utah County","counties":["Utah County"],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/617337be6c595b0182d069f3_comingoutday_LOGO_11-final.png","desc":"Savannah Skyler and Jerilyn Hassell Pool teamed up to create a graphic to allow teachers a way to signal a commitment to learning and understanding of issues faced by sexual, gender, or racial minorities and a willingness to create and maintain safe space to help those who struggle. Based on “Ring Theory” by Dr. Susan Silk\n\n• Promotes helpful and healthy patterns of support for the most vulnerable: “comfort in; dump out”\n\n• Illustrates encompassing support for Black and Indigenous People of Color (BIPOC) and trans communities\n\n• Emphasizes importance of the larger LGBTQ+ community as a resource while recognizing their need for safety, too\n\nSupport them in their goal to deliver posters and resource packets to Utah schools. Visit thier website!","web":"safespaceut.com","tel":"","email":"","addr":"","fb":"https://www.facebook.com/SafeSpaceUT","ig":""},{"id":"VK8rnjZwR229YaoVVcQuUQ","name":"Salt Lake City Gay Men's Book Club","cat":"Social Groups","county":"Salt Lake County","counties":["Salt Lake County"],"demo":["Gay Men"],"img":"https://hosting.photobucket.com/images/i/lgbtqut/Logo_-_square.jpg","desc":"This book club is primarily for gay men but anyone is welcome to attend! We meet on the third Wednesday of each month (excluding holiday weeks). We meet at the Utah Pride Center on Main Street at 6:00. Bring a friend and feel free to check out the group even if you haven't read the book! We vote on book selections about 1-3 months in advance.","web":"","tel":"","email":"","addr":"1380 S Main St, Salt Lake City, UT 84115","fb":"https://www.facebook.com/groups/276230999378620/","ig":""},{"id":"YfhvfKINQNiuRVjNzEX28Q","name":"Salt Lake City Good Time Bowling League","cat":"Social Groups","county":"Salt Lake County","counties":["Salt Lake County"],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5f5634b3c4a75f588d5f853a_5f36b2d74ec0aace07dac1d0_Untitled%2520design.png","desc":"Utah's Sunday night LGBTQS bowling league. We were founded in 1990. We are a handicap league (meaning all bowlers are welcome) that likes to have fun while we bowl. And not only do you get to bowl in a fun, relaxed, and welcoming atmosphere you are also raising money for charities. For more information and to join, join us on Facebook.","web":"","tel":"","email":"","addr":"","fb":"https://www.facebook.com/groups/saltlakegoodtimebowlingleague","ig":""},{"id":"IIXj6dL.Qhm98TykgWcP4A","name":"Salt Lake Health Center","cat":"Wellness/Medical","county":"Salt Lake County","counties":["Salt Lake County"],"demo":[],"img":"https://hosting.photobucket.com/images/i/lgbtqut/5f36ad95b2ae3f30b8d8e28b_5f36abc5c9770f898e299192_Planned_20Parenthood.jpeg","desc":"Services Offered:\n\nBirth Control\n\nHIV Services\n\nMen's Health Care\n\nMorning-After Pill (Emergency Contraception)\n\nPregnancy Testing & Services\n\nPrimary Care\n\nSTD Testing, Treatment, & Vaccines\n\nWomen's Health Care\n\nAbortion Referrals\n\nFor more information, hours, and to book online, please visit the Health Center Website.","web":"","tel":"","email":"","addr":"654 South 900 East Salt Lake City, UT 84102","fb":"","ig":""},{"id":"a.zB2MXyxRKiSA-dJHAONFA","name":"Salt Lake Mens Choir","cat":"Social Groups","county":"Salt Lake County","counties":["Salt Lake County"],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/611b35624c1e3345e28551b1_SL%20Mens%20Choir.png","desc":"Our Mission: The Salt Lake Men’s Choir is dedicated to musical excellence. The purpose of the choir is to:\n\n- Promote, perform and expand men’s choral literature as an art form.\n\n- Cultivate skills in choral singing.\n\n- Provide opportunities for self-expression.\n\n- Build bridges of understanding and tolerance among diverse communities through music.\n\n- Provide positive social and spiritual support for its members.\n\nThe Salt Lake Men’s Choir strives for:\n\n- a safe haven of friendship, support, and unity\n\n- a high standard of musical excellence\n\n- a high level of commitment\n\n- opportunities to learn and grow through choral music\n\n\nWe welcome all men who have a desire to sing and want to be part of a diverse, openhearted organization. don't worry about your musical abilities — We're all here to learn — so come and have some fun with us! Membership requires a willing heart, a desire to learn","web":"https://www.saltlakemenschoir.org/","tel":"","email":"","addr":"","fb":"https://www.facebook.com/slmenschoir/","ig":""},{"id":"E6jyu6v3Q2CbOA.jUtd.5A","name":"Salt Lake Metro Health Center","cat":"Wellness/Medical","county":"Salt Lake County","counties":["Salt Lake County"],"demo":[],"img":"https://hosting.photobucket.com/images/i/lgbtqut/5f36ad95b2ae3f30b8d8e28b_5f36abc5c9770f898e299192_Planned_20Parenthood.jpeg","desc":"Services Offered:\n\nAbortion \n\nFor more information, hours, and to book online, please visit the Health Center Website.","web":"","tel":"","email":"","addr":"160 South 1000 East, Suite 120 Salt Lake City, UT 84102","fb":"","ig":""},{"id":"Ex1lX0MZQJS0Jt.cuhpk0A","name":"Share Your Light Support Group","cat":"Support Circles","county":"Utah County","counties":["Utah County"],"demo":["LDS"],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/61733ba759f2300d0d5cbfa8_244053766_10224904060456179_6260953821558898229_n.jpg","desc":"A support group for parents and allies of LGBTQ+ family members. Held every 2nd Sunday of each month at the Grandview South Stake Center Relief Society Room in Provo, UT at 7:30 PM. Questions? Call or text Emily Harrison.","web":"","tel":"801-830-1163","email":"","addr":"1122 Grand Avenue, Provo, Utah 84604","fb":"","ig":""},{"id":"MZUQsQXoTVeGFXCSOr.HOw","name":"SLAQC","cat":"Social Groups","county":"Salt Lake County","counties":["Salt Lake County"],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/613946d1e0e1b096225dbe1b_Copy%20of%20Location%20Icon.png","desc":"SLAQC is a rock climbing group for LGBTQIA+ identified folks in Salt Lake City and the Wasatch Front. We are a peer-led group whose mission is to build community, empower LGBTQIA+ individuals in the sport of rock climbing, and create a more inclusive environment in the rock climbing community as a whole. We hold regular meetup events for climbers of all skill levels at the Front in Salt Lake, and are looking to expand into more gyms in the area and organize outdoor trips in the summer.","web":"","tel":"","email":"","addr":"","fb":"https://www.facebook.com/groups/1033369770048204/","ig":"https://www.instagram.com/slaqueerclimbers/"},{"id":"1m1i0BRxSX6ekLG3Epc02Q","name":"SLC Lesbians Bookclub","cat":"Social Groups","county":"Salt Lake County","counties":["Salt Lake County"],"demo":["Lesbian"],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/61acff959d1b1647a8dd7b5e_154539694_106939338113876_6947648242697205525_n.png","desc":"**Meetings**: The book club meets at 2 pm on the last Saturday of the month (unless noted with an *) at Under the Umbrella, our local queer bookstore. 511 W 200 S Suite 120, Salt Lake City, UT 84101. We are a trans/non-binary/bi inclusive group.\n\n**Cost**: Please bring a contribution (sliding scale $1-5) for the meeting room reservation at Under the Umbrella. If $1 a month is a barrier for you please just reach out to  slc.lesbian.bookclub@gmail.com and let us know in advance.","web":"kingsenglish.com/slc-lesbian-bookclub","tel":"","email":"slc.lesbian.bookclub@gmail.com","addr":"","fb":"facebook.com/groups/160979024045091","ig":""},{"id":"i7EoQU0eQB2GPv0qNfRLSg","name":"SLC LGBT+ Friendly Housing","cat":"Queer Housing","county":"","counties":[],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/611b3421de6130364257491f_29472429_10156286167486683_3775308461143752704_n.jpg","desc":"LGBT+ Friendly Housing was created so that the LGBT+ community could have a space to more easily and safely find housing opportunities in Utah.\n\n3 Easy Rules - If you can't follow them you will be removed from the group:\r\n1- No bullying or hate speech.\r\n2- Be kind ❤️\r\n3- If you have any questions or concerns, contact group creator, Lauren Hamilton directly.","web":"","tel":"","email":"","addr":"","fb":"https://www.facebook.com/groups/209397079601455","ig":""},{"id":"ohW0zPLdRpChia8Hiufk.w","name":"SLC Queer Housing","cat":"Queer Housing","county":"Salt Lake County","counties":["Salt Lake County"],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/611494010dac64fbb6df8b36_groups-default-cover-photo-2x.png","desc":"A Facebook group for those looking for queer freindly housing in Salt Lake City.","web":"","tel":"","email":"","addr":"","fb":"https://www.facebook.com/groups/1910230212576888/about","ig":""},{"id":"KkZWarOhQbK2n.ar2PUMiA","name":"SLCC Queer Student Association","cat":"College Resources","county":"Salt Lake County","counties":["Salt Lake County"],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/611b35785c8255f3da67bfd2_download%20(4).png","desc":"Queer Student Association is a social support & educational group for LGBTQ+ people & their allies. We are dedicated to promoting openness and equality, maintaining confidentiality, supporting diversity, serving the public, and furthering a positive image for the LGBTQ+ community.\n\nSalt Lake Community College has a strong initiative to enhance the quality of life of lesbian, gay, bisexual, transgender, queer, and questioning SLCC students, faculty, and staff in an environment that is welcoming, positive, and safe, by increasing the SLCC community's awareness, understanding, and inclusion of its lesbian, gay, bisexual, transgender, queer, and questioning members. We will achieve this mission by providing:\n\nResources to LGBTQ+ students, staff, and faculty\n\nResources to allies\n\nEducation on the terminology, the history, and the current issues effecting the LGBTQ+ community\n\nSafe Zone traini","web":"http://www.slcc.edu/lgbtq/queer-student-association.aspx","tel":"","email":"SafeZone@slcc.edu","addr":"4600 South Redwood Road, Salt Lake City, UT 84123","fb":"","ig":""},{"id":"dx4-2ZobSOWCWmuD4P7XUQ","name":"So You're Mormon and Gay","cat":"Blog","county":"","counties":[],"demo":["LDS"],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/60534d7664edf561c5ffb750_IMG_20210317_221620_562.jpg","desc":"Hi, I'm Kelly! I'm 29 years old, born and raised in the San Francisco Bay Area, and currently living and working in Salt Lake City. I am the youngest in a family of five and was spoiled and loved like crazy (the youngest child spot is definitely the best in my opinion). I love being outside, traveling, and all sports, especially basketball (go Warriors!). I played basketball at Lehigh University during my undergrad and then went on to graduate school at BYU. I joined the Church of Jesus Christ of Latter-day Saints in 2010 when I was 19, served a mission in Nagoya, Japan (日本が大好き!), and occassionally attend my ward in Salt Lake. Oh, and yes, I'm gay!\n\n\nI wanted to create this blog to share my own story and the stories of my LGBTQ Mormon friends. When I started to realize I might be gay (it only took me 23 years to realize my \"really close friendships\" and \"girl crushes\" might be something ","web":"soyouremormonandgay.blogspot.com","tel":"","email":"","addr":"","fb":"","ig":"https://instagram.com/soyouremormonandgay?igshid=1hosg6gop3nwv"},{"id":"e-f7WBM2SOWCzcX0f3WAYg","name":"South Jordan Health Center","cat":"Wellness/Medical","county":"Salt Lake County","counties":["Salt Lake County"],"demo":[],"img":"https://hosting.photobucket.com/images/i/lgbtqut/5f36ad95b2ae3f30b8d8e28b_5f36abc5c9770f898e299192_Planned_20Parenthood.jpeg","desc":"Services Offered:\n\nBirth Control\n\nHIV Services\n\nMen's Health Care\n\nMorning-After Pill (Emergency Contraception)\n\nPregnancy Testing & Services\n\nPrimary Care\n\nSTD Testing, Treatment, & Vaccines\n\nWomen's Health Care\n\nAbortion Referrals\n\nFor more information, hours, and to book online, please visit the Health Center Website.","web":"","tel":"","email":"","addr":"1091 West South Jordan Parkway, Suite 100 South Jordan, UT 84095","fb":"","ig":""},{"id":"87jYfOtTQjyqayimV9CQ-A","name":"Southern Utah University Pride Alliance","cat":"College Resources","county":"Washington County","counties":["Washington County"],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5f5642cf508736f345ad976b_SUU%20Pride%20Alliance.png","desc":"Pride Alliance is a committee comprised of students, staff, faculty, and administrators dedicated to supporting the Lesbian, Gay, Bisexual, Transgender, Queer, Intersex, and Asexual (LGBTQIA+) community on the campus of Southern Utah University (SUU)The SUU Pride Alliance works to provide resources such as the SUU LGBTQIA+ and Allies Community CAPS Group, The Safe Space, and the Pride and Equality Club.","web":"suu.edu/pridealliance/","tel":"","email":"pridealliance@suu.edu","addr":"351 W University Blvd, Ceder City Utah, 84720","fb":"https://www.facebook.com/pages/category/Social-Club/PAEC-at-SUU-Pride-And-Equality-Club-2619248194772375/","ig":""},{"id":"ShGqEPC3R7-RulZC6Chf.w","name":"St. George Health Center","cat":"Wellness/Medical","county":"Washington County","counties":["Washington County"],"demo":[],"img":"https://hosting.photobucket.com/images/i/lgbtqut/5f36ad95b2ae3f30b8d8e28b_5f36abc5c9770f898e299192_Planned_20Parenthood.jpeg","desc":"Services Offered:\n\nBirth Control\n\nHIV Services\n\nMen's Health Care\n\nMorning-After Pill (Emergency Contraception)\n\nPregnancy Testing & Services\n\nPrimary Care\n\nSTD Testing, Treatment, & Vaccines\n\nWomen's Health Care\n\nAbortion Referrals\n\nFor more information, hours, and to book online, please visit the Health Center Website.","web":"","tel":"","email":"","addr":"595 South Bluff Street Suite 1 Saint George, UT 84770","fb":"","ig":""},{"id":"OZ8barp0S4WiljLciOrg.w","name":"Stockton Powers Memorial Scholarship","cat":"College Resources","county":"","counties":[],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5f5630a01dc0c314cac46b3f_5f36b24f6baf8e9e7fa053d0_Stockton%2520Powers%2520Memorial%2520Scholarship.png","desc":"GENERAL INFO\n\nThe Stockton Powers Memorial Scholarship is available to those who apply for themselves or for those who believe there is someone who is deserving of this scholarship. The scholarship may be applied to tuition cost, book fees, housing, educational tools, and daily expenses. Recipient will receive a certain dollar amount according to needs*. Please contact us with any questions about eligibility or if you need any help applying.\n\nELIGIBILITY CRITERIA\n\nIn order to be eligible to apply for the Stockton Powers Memorial Scholarship, you must meet the following requirements:\n\nHigh School Senior to 25 years of age\n\nFurthering your education\n\nUtah applicants only\n\nMaintain a GPA of 2.8 or above \n\nWHY WE DO ITStockton was born in Salt Lake City, UT on May 5, 1999. He was a long-awaited blessing for our family. Stockton was very adventurous. Whatever he loved, he gave 110%. He loved ","web":"https://www.standingforstockton.com/","tel":"","email":"","addr":"","fb":"","ig":""},{"id":"KPCWMwu-Sa-Y4S5vFCRMuw","name":"Stonewall Sports","cat":"Social Groups","county":"Salt Lake County","counties":["Salt Lake County"],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5fbd74565cd65ce2d7a50639_download%20(13).png","desc":"WHO WE ARE: \n\nStonewall Sports - Salt Lake City is an LGBTQ+ and Ally not-for-profit sports league. We strive to develop a well-connected and diverse community through organized competition and social or fundraising events.\n\n \nVISION: Our Vision is that EVERY person should have the ability to feel comfortable playing organized sports and that we have the responsibility to give back to our community. \n\nMISSION: Our Mission is to provide an inclusive, low cost, high FUN sports league that is managed as a non-profit with a philanthropic heart. \n\nStonewall Sports Salt Lake City was founded in 2018 to create an inclusive community that has fun through playing sports and giving back with a philanthropic heart. We are an LGBTQ+ organization that celebrates allies and people from all walks of life. Please find a sport that you love and join! We hope you can meet some new friends and have a blast","web":"http://www.stonewallsportsslc.org/","tel":"","email":"saltlakecity@stonewallsports.org","addr":"","fb":"https://www.facebook.com/SLCSTONEWALL/","ig":"https://www.instagram.com/stonewallsportsslc/"},{"id":"G8tGnuBNQcueevw8wJ14QA","name":"SUU Pride Alliance Sexuality and Gender Resources","cat":"College Resources","county":"Washington County","counties":["Washington County"],"demo":["LGBTQ+ Adult","Student"],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5f5642cf508736f345ad976b_SUU%20Pride%20Alliance.png","desc":"The Center for Diversity and Inclusion is committed to advocating for our lesbian, gay, bisexual, trans, queer, intersex, and asexual (LGBTQIA+) students, staff, and community members. We believe in creating an environment where sexual and gender diversity is respected and celebrated. As a Center, we resist any actions contrary to the health and success of our LGBTQIA+ communities.","web":"https://www.suu.edu/pridealliance/resources.html","tel":"435-865-8482","email":"pridealliance@suu.edu","addr":"351 W University Blvd. Cedar City, Utah 84720","fb":"https://www.facebook.com/SUUPAEC/","ig":"https://www.instagram.com/suu_paec/"},{"id":"kSY-1gQjTMupHhFLNujwkg","name":"TEA of Utah","cat":"Education/Advocacy","county":"","counties":[],"demo":["Trans"],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5fb96b6ee5e1d88b0072fdc3_TEA.jpg","desc":"To our LGBTQIA+ students, please know you belong here. You are supported, you are valid, and you are not alone. We look forward to working alongside you.","web":"https://www.teaofutah.org/","tel":"","email":"","addr":"","fb":"https://www.facebook.com/TEAofUtah.org/","ig":""},{"id":"75jAyg.OQ-GsEl7O1p2N.w","name":"Teen Support Group","cat":"Support Circles","county":"Cache County","counties":["Cache County"],"demo":["Young Adult"],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5f358fc72b040487de0d14ba_Cache%20Pride.jpg","desc":"Cache Pride Center gives youth a physical and emotionally safe space. Each week we provide a hot meal and check-in with our youth. Our groups are tailored to the needs of our youths through support groups, one-on-one therapy, individually crafted lessons to develop lifelong skills, creative expression workshops, games, peer support, guided discussions, sexuality education, and during the school year, an hour of tutoring to see our youth succeed in school. During our groups, our youth have access to food, clothing, and hygiene items to provide for their basic needs. We also provide assistance in accessing affirming health care, mental health care, local organizations, suicide prevention and additional relevant resources.Teen (Ages 14-18)596 E 900 N, Logan, UT 84321Fridays 5pm – 8pmFor LGBTQIAP+ youth","web":"cachepridecenter.org","tel":"(435) 363-5473","email":"cachepridecenter@gmail.com","addr":"","fb":"https://www.facebook.com/CachePrideCenter/","ig":""},{"id":"jHIDim61T3CcvZ4xHRgIzQ","name":"The OUT Foundation","cat":"College Resources","county":"Utah County","counties":["Utah County"],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/6125a653c64d94f83d551580_Bee_logo_Artboard%201.png","desc":"Our mission is to empower the LGBTQ+ students and alumni of Brigham Young University in achieving their intellectual, social, and professional potential. We do this by completing initiatives based on the needs of our students and alumni.","web":"https://www.theout.foundation/","tel":"(801) 691-6149","email":"info@theout.foundation","addr":"","fb":"https://www.facebook.com/theOUTfoundation/","ig":"https://instagram.com/theoutfoundation?igshid=1q6cgtiz1prc8"},{"id":"FGJaqfbKT6Sm9h3zw5VhHA","name":"The Royal Court of the Golden Spike Empire","cat":"Philanthropy","county":"Salt Lake County","counties":["Salt Lake County"],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/6114929acf584a497d4e49af_GSA.jpg","desc":"The Royal Court is a registered 501 c(3) organization and is, in fact, Utah’s oldest LGBTQ+ Organization. Founded in 1976, we were originally established as a social organization for the LGBTQ+ community of Utah to have a safe place to gather and raise money for various groups and organizations in Utah.  We have been a part of many firsts in the Salt Lake City LGBTQ+ community and even started the yearly pride celebration that is so popular today.  Many members of our Founders Table are still around and still a part of the many great things that we do.\n\nAs the years progressed, and the issues facing the community changed, our focus changed to helping individuals in need. We began focusing on people dealing with Cancer, HIV / Aids, the Youth, and Transgender individuals, just to name a few. We have many funds that our community members may apply to for financial assistance.  We have our P","web":"rcgse.org","tel":"","email":"info@rcgse.org","addr":"https://www.facebook.com/rcgse","fb":"","ig":""},{"id":"AZ5c1MHcR4iQzmjVTsPmDA","name":"The Utah Hearth","cat":"Speaker Series","county":"Salt Lake County","counties":["Salt Lake County"],"demo":["LDS"],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/603bd6ae966471da0bdba72f_THE%20HEARTH%20(2).png","desc":"An inclusive community of LGBTQ Latter-Day Saints and those who love them. The Utah Hearth is an organization that invites monthly speakers to share their stories and messages in an effort to support, encourage, and offer hope to LGBTQ Latter-Day Saint members and those that love them. Attendants usually comprise of LGBTQ individuals and family members that are current, or former, members of The Church of Jesus Christ of Latter-Day Saints. Events are usually held the first Sunday of every month in Holladay. Past speakers have included Barbara and Steve Young (NFL/Love Loud Foundation), George and Alyson Deussen (Stockton Powers Memorial Scholarship/Peculiar), and Richard Ostler (Listen Learn and Love Podcast).","web":"","tel":"","email":"","addr":"","fb":"https://www.facebook.com/groups/320445228673183","ig":""},{"id":"YrPjRAG2QACU6YiBdeZ2Dg","name":"Trans* Mormons, Families, & Friends Online Community","cat":"Online Community","county":"","counties":[],"demo":["Trans","LDS"],"img":"https://hosting.photobucket.com/images/i/lgbtqut/5f663c89dc4ac15aa61147df_novo-logo-afirma_o_n.png","desc":"Affirmation Trans* is an inclusive group for Trans* Mormons, and their friends and family. We encourage learning and education of Trans* topics and how they relate to both daily life and the restored gospel. Our goal is to create a welcoming community for Trans* brothers and sisters in Affirmation, where we can find a safe space to learn, grow, and teach through uplifting discussion and heartfelt stories.","web":"","tel":"","email":"","addr":"","fb":"https://www.facebook.com/groups/674629102608451/","ig":""},{"id":"0H6ayeU1TMqFP1FddjAIeg","name":"TransAction","cat":"Support Circles","county":"Salt Lake County","counties":["Salt Lake County"],"demo":["Trans"],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/60b3f1a3f51b70dd9c04c702_11080978_353214928198566_330726561824751880_n.jpg","desc":"The mission of TransAction is to create social community, offer mentorship, and teach life skills to the trans and gender non-binary communities.","web":"","tel":"801-539-8800","email":"transaction@utahpridecenter.org","addr":"1380 S. Main Street, Salt Lake City","fb":"https://www.facebook.com/transactionut/","ig":""},{"id":"yAOVjMjTSe2fBpQ96Map2w","name":"Transactive LDS Support Group","cat":"Online Community","county":"","counties":[],"demo":["Trans","LDS"],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/60b3f1a3f51b70dd9c04c702_11080978_353214928198566_330726561824751880_n.jpg","desc":"A faith affirming group to help Transgender/Intersex/Gender Dysphoria individuals and their family members support one another. Group members may be active or former LDS to join, as long as a tone of respect for LDS beliefs is maintained.","web":"","tel":"","email":"","addr":"","fb":"https://www.facebook.com/TransActiveLDS/?ref=page_internal","ig":""},{"id":"CFn4NwTLS0GyLVCbYChwtw","name":"Transgender Adults Friendship Circle","cat":"Support Circles","county":"Salt Lake County","counties":["Salt Lake County","Washington County","Utah County"],"demo":["Trans"],"img":"https://hosting.photobucket.com/images/i/lgbtqut/Encircle_Logo.png","desc":"This friendship circle is for transgender folx over the age of 18. \n\nFriendship Circles?\nThese groups are designed to provide connection with folx you identify with and help you manage the trials you encounter every day. Friendship Circles create an opportunity for you to take control and thrive in your own life.\n\nFriendship Circles provide opportunities for sharing, connection, and support through discussion of issues and experiences relevant to each group, often exploring the intersectionality of conservative cultures, spirituality, sexuality, social issues, transitional issues, and health issues and the ways it impacts us. The groups also provide a great support network—members in similar circumstances with similar feelings with whom they can share in an open and unedited fashion.\n\nGroups organized by sexuality, age, and/or gender identity.\n\nFor schedules and more information please v","web":"","tel":"","email":"","addr":"","fb":"","ig":""},{"id":"dYx8AdLsQ9SecbSdnEJREQ","name":"Trevor Space","cat":"Online Community","county":"","counties":[],"demo":["LGBTQ"],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/611492cfa68fb607cc85bda6_the-trevor-project-donation-o.jpg","desc":"Start meeting LGBTQ friends today!\n\nTrevorSpace is an affirming international community for LGBTQ young people ages 13-24. Sign up and start a conversation now.","web":"https://www.trevorspace.org/?utm_source=trevor_website&utm_medium=web&utm_campaign=nav_bar","tel":"","email":"","addr":"","fb":"","ig":""},{"id":"9c.fhO7DSfGwy0stlvMpxQ","name":"University of Utah LGBT Resource Center","cat":"College Resources","county":"Salt Lake County","counties":["Salt Lake County"],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/61149051fa744a3212772e2c_BlockU_400px.png","desc":"The LGBT Resource Center empowers lesbian, gay, bisexual, transgender, queer, questioning, intersex, asexual/aromatic (LGBTQIA+) students to grow as leaders and learners by supporting students in navigating university systems, exploring their identities, finding community, and developing as leaders with a social justice lens.","web":"https://lgbt.utah.edu/","tel":"801-587-7973","email":"lgbtrc@sa.utah.edu","addr":"200 S. CENTRAL CAMPUS DR, SALT LAKE CITY, UT 84112","fb":"https://www.facebook.com/LGBTResource/","ig":"https://www.instagram.com/lgbtresource/?hl=en"},{"id":"j8Q1Rs8gT1SHABwWxtgryg","name":"University of Utah Transgender Health Program","cat":"Wellness/Medical","county":"Salt Lake County","counties":["Salt Lake County"],"demo":["Trans"],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/61149051fa744a3212772e2c_BlockU_400px.png","desc":"The Transgender Health Program at the University of Utah Health brings quality healthcare to trans adults and teens from all walks of life. We welcome all identities and expressions seeking our services. We understand that every trans or gender-nonconforming person’s experience is unique. Our doctors will be there to give you endless support wherever your journey takes you.\n\nYour comfort and trust matter the most to us. We provide a safe, trans-affirmative environment where patients can comfortably access the full range of health services they need. This includes primary care; surgery and hormone therapy; and mental health, counseling, and nutrition services. We will even help you navigate your care and finances to find the best care that fits your budget.","web":"healthcare.utah.edu/transgender-health","tel":"801-213-2195","email":"transgenderhealth@hsc.utah.edu","addr":"","fb":"","ig":""},{"id":"9BkpJzZER7-7o7S5V1jfKQ","name":"Utah AIDS Foundation","cat":"Wellness/Medical","county":"Salt Lake County","counties":["Salt Lake County"],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5fb286359815020668a1db2a_UAF.jpeg","desc":"MISSION\n\nUtah AIDS Foundation, through client-driven services, champions sexual health and overall well-being for those living with or at risk for HIV and other STIs.\n\nVISION \n\nUtah AIDS Foundation works to achieve a future where everyone has equitable access to HIV and STI education, prevention, treatment, and care. \n\nSERVICES\n\nThe Utah AIDS Foundation provides support to people living with HIV/AIDS, and prevention services for those at risk for HIV.    We offer assistance and expertise to anyone struggling with the complex issues that surround HIV, because we believe that no one should have to confront this disease alone.\n\n - HIV/STI Testing\n\n- HIV/STI Info Hotline\n\n- Case Management & Support\n\n- Food Bank\n\n- Educational Presentations\n\n- Syringe Exchange","web":"utahaids.org","tel":"801-487-2323","email":"","addr":"1408 1100 E, Salt Lake City, UT 84105","fb":"https://www.facebook.com/utahaidsfoundation","ig":"https://www.instagram.com/utahaidsfoundation/"},{"id":"60OfnduNReWDinYhDh7XOw","name":"Utah Asexuals","cat":"Social Groups","county":"Salt Lake County","counties":["Salt Lake County"],"demo":["Asexual"],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5fb2d7100e504cfd3b8145c5_download.png","desc":"Utah Asexuals strives to develop a welcoming and open environment that stands for inclusion, affirmation, and support for all the asexual &amp; aromantic community of Utah.","web":"","tel":"","email":"utahasexuals@gmail.com","addr":"","fb":"https://www.facebook.com/UTAces","ig":""},{"id":"DBmBhJTGQKiH9x16w3FIUA","name":"Utah Bears","cat":"Social Groups","county":"Salt Lake County","counties":["Salt Lake County"],"demo":["Gay Men"],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/6114931ba68fb60b9085bdd4_idRc1AK6.jpg","desc":"We are a men’s membership-based social and service group organized and operated exclusively to support and to promote diversity and inclusion in our community; foster positive community involvement; and provide opportunities which enhance the personal growth of our members, the Bear community, and the LGBT community as a whole.","web":"utahbears.com","tel":"","email":"info@utahbears.com","addr":"","fb":"https://www.facebook.com/utahbears/","ig":"https://www.instagram.com/utahbearsinc/"},{"id":"46Lawh8hTj6.cmMUJZTMlw","name":"Utah Center for Legal Inclusion","cat":"Professional Services","county":"Salt Lake County","counties":["Salt Lake County"],"demo":["Adults"],"img":"https://storage.googleapis.com/glide-prod.appspot.com/uploads-v2/vZEd46xUe6vz0E68sGvW/pub/OvuFnk21v0chv4YquLTy.png","desc":"The Utah Center for Legal Inclusion (UCLI) is a 501(c)(3) nonprofit organization dedicated to advancing the goals of equity and inclusion in Utah’s legal profession. By coordinating with the Utah State Bar and its affinity groups, legal employers, government agencies, educational institutions, and community partners, UCLI strives to enhance organizational inclusion, facilitate educational opportunities and professional advancement for students and attorneys with diverse backgrounds, assist in eliminating bias in Utah’s justice system, and track the progress of legal inclusion efforts throughout the state. UCLI invites all to participate in its inclusion initiatives, which will help strengthen Utah’s legal institutions in an increasingly diverse state.","web":"https://www.utahcli.org","tel":"(801) 746 – 5221","email":"ucli@utahcli.org","addr":"645 South 200 East\nSalt Lake City, Utah 84111","fb":"https://www.facebook.com/UtahUCLI/","ig":"https://www.instagram.com/utahcli"},{"id":"WhEuMxUmSmSTmApqMSHAnw","name":"Utah Coalition Against Sexual Assault - LGBTQ Coordinating Counsel","cat":"Education/Advocacy","county":"Salt Lake County","counties":["Salt Lake County"],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/61149346f9a74f1e9aeb944c_logo-comb.png","desc":"Our Statewide LGBTQ Coordinating Council Advisory Council (Council) is a permanent advisory council located within the Utah Coalition Against Sexual Assault (UCASA). It was established by a vote of the Board of Directors in 2017 to ensure that LGBTQ survivors and victims of sexual violence are represented in victim services organizations, institutions, and partnerships that serve sexual violence survivors statewide. This includes but is not limited to:\n\nEnsuring adequate representation of LGBTQ survivors in all Sexual Assault Response Teams (SARTs) statewide.\n\nEnsuring that LGBTQ-affirming training is provided statewide to sexual violence programs, law enforcement, and any other institution that interacts with sexual violence survivors.\n\nEnsuring that print, online, and others forms of information are available online to improve services for LGBTQ survivors of sexual violence.\n\nProducing","web":"https://www.ucasa.org/lgbtqq","tel":"801-746-0404","email":"info@ucasa.org","addr":"284 West 400 North Salt Lake City, Utah 84103","fb":"","ig":""},{"id":"ldTmxD4IRViHvtbh8.PiWw","name":"Utah FAM","cat":"Education/Advocacy","county":"","counties":[],"demo":["LGBTQ"],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/60b3a872bb547ffdf40cf9e3_Untitled%20design%20(8).png","desc":"Founded Kody Colvin, Alli Martin, and Tyson Price in 2016, Utah FAM works to make Utah schools better for LGBTQ+ teachers and students. Utah FAM has delivered hundreds of professional learning workshops, seminars, and trainings at schools, companies, and homes. We organize monthly educator socials via Zoom open to teachers across the state. We make new friends, celebrate successes, share ideas and resources, and provide individualized support.\n\nUtah FAM educators seek to empower LGBTQ+ teachers and allies to embed LGBTQ+ affirming practice into schools and classrooms.","web":"https://utahfam.org/","tel":"","email":"","addr":"","fb":"https://www.facebook.com/FAM.SLC","ig":"https://www.instagram.com/fam_utah/"},{"id":"FXwte0KgT4KRB32LiU7LsQ","name":"Utah Fertility Clinic","cat":"Wellness/Medical","county":"Salt Lake County","counties":["Salt Lake County","Weber County","Washington County","Utah County"],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/61149380a2c309164b4cf77e_unnamed%20(1).jpg","desc":"LGBTQ Family Building\n\nEveryone’s journey to parenthood is unique, and we strive to make this experience as seamless and comfortable as possible.  Whether you need donor sperm, donor eggs, or a gestational carrier (surrogate), our reproductive specialists and staff will help you to navigate the process to best fit your needs.  LGBTQ family building may involve intrauterine inseminations or In Vitro Fertilization, and we welcome the opportunity to help all couples or individuals conceive.\n\nFertility Treatment for Lesbian Couples\n\n\nTreatment for lesbian couples is typically intrauterine inseminations (IUI) or In Vitro Fertilization (IVF) using donor sperm.  A consultation with one of our physicians and review of both partners’ medical history can help determine the most optimal treatment options. Questions to consider are whose eggs will be used and who will carry the baby.\n\nTreatment for ","web":"utahfertility.com","tel":"801-785-5100","email":"","addr":"","fb":"https://www.facebook.com/UtahFertility","ig":"https://www.instagram.com/utahfertilitycenter/"},{"id":"MqC4lt.-QU2xEH2aYQPyhw","name":"Utah Gay Fathers Association","cat":"Support Circles","county":"","counties":[],"demo":["Gay Men"],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/611493b6f1c289074e6c8750_430720_255500641198412_2020205657_n.jpg","desc":"UGFA exists to provide support, community, and educational resources to Utah’s gay fathers and future fathers.\n\nThe Utah Gay Fathers Association is a group dedicated to holding monthly, in-person social gatherings of gay dads. Our focus is to embrace, affirm, and improve ourselves as gay fathers and men; to socialize and share the unique and universal joys, strengths, and challenges that we face as gay fathers in Utah. \n\nAs a group we have discussions about what it means to be a gay father, current issues group members may be facing, helpful suggestions, venting, personal therapeutic or legal recommendations, etc.","web":"","tel":"","email":"utahgayfathers@gmail.com","addr":"","fb":"https://www.facebook.com/utahgayfathers/","ig":""},{"id":"rOrhlNG0QiyDcdrErb2zRQ","name":"Utah LGBT Young Adult Hangouts","cat":"Social Groups","county":"Davis County","counties":["Davis County"],"demo":["Young Adult"],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/60a7d80564267c639e4bb108_Screenshot_20210212-160905-636.png","desc":"This is a safe place for LGBT+ teens and young adults to hangout, make friends, and connect with others. Events and Hangouts are held at the beginning of every month, hosted by Jessie Funk and Robby Talbot. Straight Allys wanted and welcome! Everyone is welcome, accepted, and loved. Come join! ♥️","web":"","tel":"","email":"","addr":"","fb":"https://www.facebook.com/groups/574420233039108","ig":"https://instagram.com/utahlgbthangouts?utm_medium=copy_link"},{"id":"4S-d-PPYQdCPPeM5aKN0uA","name":"Utah LGBTQ+ Chamber of Commerce","cat":"Professional Services","county":"Salt Lake County","counties":["Salt Lake County"],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/611493d1cd52a7edb255b725_event-featured-Mic-1553122300.png","desc":"The Utah LGBTQ+ Chamber of Commerce is open to corporations of all sizes, sole proprietors and independent agents regardless of sexual orientation, gender identity, or gender expression. This is a great place to meet other professionals, make business contacts, promote your business and work for the enhancement of Utah’s LGBTQ+ community","web":"https://www.utahlgbtqchamber.org/","tel":"385-743-9211","email":"boardofdirectors@utahlgbtqchamber.org","addr":"","fb":"https://www.facebook.com/utahgaychamber/","ig":"https://www.instagram.com/utah.gay.chamber/"},{"id":"OLg2IzQCSGyMo.mQuwiDFQ","name":"Utah LGBTQIA+/SSA Friendly Housing","cat":"Queer Housing","county":"","counties":[],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/611494010dac64fbb6df8b36_groups-default-cover-photo-2x.png","desc":"A Facebook group for those looking for LGBTQIA+/SSA freindly housing in Utah.","web":"","tel":"","email":"","addr":"","fb":"https://www.facebook.com/groups/utahlgbthousing/about","ig":""},{"id":"Hc8eW5DZTFCdx.0CuaXCNA","name":"Utah Pride Center","cat":"Pride Center","county":"Salt Lake County","counties":["Salt Lake County"],"demo":[],"img":"https://hosting.photobucket.com/images/i/lgbtqut/Logo_-_square.jpg","desc":"Mission: Utah Pride unites, empowers and celebrates Utah’s diverse LGBTQ+ community by providing a safe and welcoming space for education, partnership, service, and events which advance our collective health, wellness and success.","web":"utahpridecenter.org","tel":"+1 801 539 8800","email":"information@utahpridecenter.org","addr":"1380 South Main, SLC, UT, 84115","fb":"https://www.facebook.com/UTpridecenter/","ig":"https://www.instagram.com/utahpridecenter/?hl=en"},{"id":"aXDW.ri2T1WVHZ7CN0nfdg","name":"Utah Pride Center Counseling","cat":"Mental Health/Counseling","county":"Salt Lake County","counties":["Salt Lake County"],"demo":[],"img":"https://hosting.photobucket.com/images/i/lgbtqut/Logo_-_square.jpg","desc":"The Utah Pride Center’s Community Counseling practices an affirmative approach to psychotherapy, working with our young and older folks to uncover their interpersonal concerns within the context of their gender identity or sexual orientation.Our affirmative and supportive approach involves a strong focus on the therapeutic alliance, with therapists serving as advocates for the client and being mindful of the LGBTQ+ experience. Using this developmental, evidence-based and culturally sensitive understanding, our therapists engage in a meaningful and queer supportive approach.","web":"http://utahpridecenter.org/mental-health","tel":"801-539-8800","email":"therapy@utahpridecenter.org","addr":"1380 South Main, SLC, UT, 84115","fb":"","ig":""},{"id":"a.WrxHMsgSaiwVqirzNH5XA","name":"Utah Rainbow Hikers","cat":"Social Groups","county":"Salt Lake County","counties":["Salt Lake County","Cache County","Davis County","Weber County"],"demo":[],"img":"https://storage.googleapis.com/glide-prod.appspot.com/uploads-v2/NSfaaNV0fRhAK9yZqEUi/pub/egf4RgUsaw6OGJcfM1eq.jpg","desc":"A queer, trans, LGBTQ+ inclusive hiking group in Northern Utah. Join us as we create an inclusive outdoor community for us by us!","web":"","tel":"","email":"","addr":"","fb":"https://www.facebook.com/utahrainbowhikers","ig":"https://www.instagram.com/utahrainbowhikers/"},{"id":"uuVrXGNaRHizMkMEhS0Nyg","name":"Utah SAGE","cat":"Support Circles","county":"Salt Lake County","counties":["Salt Lake County"],"demo":["Senior"],"img":"https://hosting.photobucket.com/images/i/lgbtqut/Logo_-_square.jpg","desc":"SAGE provides services and resources for the LGBTQ senior community.  SAGE has four foundational pillars and five areas of focus that support those foundational pillars.  Every program, group or event is designed with that support in mind.  SAGE supports each person so they can live their best senior lives.\n\nFOUNDATIONAL PILLARS\n- Community Education\n- Provider Education\n- Social Needs\n- Advocacy\n\n\nAREAS OF FOCUS SUPPORTING THE PILLARS\n\n- Socialization (events, activities, functions, gatherings, outings, travel, networking)Emotional (relationships, love, caregiving, caretaking)\n- Physical (housing, healthcare, transportation, financial, sexual health/well being, exercise)- \n- Spiritual (connectivity, self-awareness, renewal, self-enlightenment, re-invention and evolving)\n\n\nYou may reach Deb Hall - Director of Ault Programs below. Telephone extension x1017","web":"https://www.utahpridecenter.org/senior-programs","tel":"801 539 8800","email":"debhall@utahpridecenter.org","addr":"","fb":"","ig":""},{"id":"D4MXtt0nQn-UBUGaW3TxAQ","name":"Utah Trevor Project","cat":"Crisis","county":"","counties":[],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/60b3ba3cfb2fc9c72f3bd236_34506545_1987836091291179_115008478178705408_n.jpg","desc":"Utah Ambassador Commitee for The Trevor Project. The Trevor Project provides crisis & suicide intervention services to 200K+ youth annually.","web":"","tel":"","email":"","addr":"","fb":"https://www.facebook.com/utahtrevorproject/about/?ref=page_internal","ig":"https://instagram.com/utahtrevorproject?utm_medium=copy_link"},{"id":"2PDC4LA7R4WuXscHz8PdXg","name":"Utah Valley Health Center","cat":"Wellness/Medical","county":"Utah County","counties":["Utah County"],"demo":[],"img":"https://hosting.photobucket.com/images/i/lgbtqut/5f36ad95b2ae3f30b8d8e28b_5f36abc5c9770f898e299192_Planned_20Parenthood.jpeg","desc":"Services Offered:\n\nBirth Control\n\nHIV Services\n\nMen's Health Care\n\nMorning-After Pill (Emergency Contraception)\n\nPregnancy Testing & Services\n\nPrimary Care\n\nSTD Testing, Treatment, & Vaccines\n\nWomen's Health Care\n\nAbortion Referrals\n\nFor more information, hours, and to book online, please visit the Health Center Website.","web":"","tel":"","email":"","addr":"1086 North 1200 West Orem, UT 84057","fb":"","ig":""},{"id":"0H4DhOt6TNegCYDORtIIlg","name":"VentureOUT Utah","cat":"Social Groups","county":"","counties":[],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5f2cdc847f3202dc59be00e6_5f2c4f1cfb9fc058dd273767_103776206_10217058209786670_8504971671522307530_o.jpeg","desc":"LGBT friendly group, welcome to all. It is our goal to promote adult, amateur outdoor recreation regardless of age, ability, gender identity, or sexual orientation. We want to inspire a sense of community and comradeship between members and participants. Group members are encouraged to share their upcoming outdoor activities so that others may join in the fun.We love the outdoors and chances are, you do too! Getting OUTside is fun! We are what we want to be, but primarily focused as an outdoor camping and hiking group. Going outdoors or hosting a social event? We like those who will make just about any excuse to get together for a good time and outdoor recreation. See you on the trail!","web":"","tel":"","email":"","addr":"","fb":"https://www.facebook.com/groups/Venture.OUT.Utah","ig":""},{"id":"cZkVT0U9QC-KPmgHTSn.-w","name":"Voices of Hope","cat":"Video Project","county":"","counties":[],"demo":["LDS"],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5fb495d33c18f3515b791d62_north%20star.jpg","desc":"The personal stories shared on this site serve as an extension of the book, the Voices of Hope. It is a living repository of faithful members of The Church of Jesus Christ of Latter-day Saints sharing their stories of how they seek to reconcile their sexual orientation or gender identity with their faith. you'll hear how they have chosen to embrace the restored gospel, the inherent challenges they face, and how they’ve found peace in their decisions.","web":"northstarlds.org/voices-of-hope","tel":"","email":"","addr":"","fb":"","ig":""},{"id":"qSwkVcceTxWftG-jN2FK6g","name":"Volunteers of America (VOA) Youth Resource Shelter","cat":"Homeless","county":"Salt Lake County","counties":["Salt Lake County"],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/6114941a500330006545afb6_3308_ut-homeless_youth_resource_center_kiq.jpg","desc":"We provide year-round support for individuals living on the street through basic need items, education assistance, employment services and housing assistance.","web":"voaut.org/homeless-youth-services","tel":"(801) 363-9414","email":"","addr":"888 SOUTH 400 WEST, SLC, UT 84101","fb":"http://www.facebook.com/voaut","ig":"https://www.instagram.com/voaut/"},{"id":"AYS5EyYESKel48gf0YuszA","name":"We're Here, We're Queer: A Proclamation to the World","cat":"Community Project","county":"","counties":[],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/6181ce5c75bd9f17ec52e023_241492242_636212557754720_1443494479478125908_n.jpg","desc":"An anthology project that will include creative pieces from queer Mormons around the world about how they integrate their spirituality and queerness🌈🐝","web":"hereandqueermormon.wixsite.com/queermormonanthology","tel":"","email":"","addr":"","fb":"https://www.facebook.com/Were-Here-Were-Queer-A-Proclamation-to-the-World-103240898773969","ig":"https://www.instagram.com/aqueermormonanthology/"},{"id":"419P0HtSRquVxt9gop.pcw","name":"Weber State LGBT Resource Center","cat":"College Resources","county":"Weber County","counties":["Weber County"],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/6125aefb9ca036607271dfa9_10712629_959404910754134_768681519791725567_o.jpg","desc":"“Cultivating a welcoming and safe environment for the LGBT community, their family, friends and allies through access learning and support.\"\n\nLGBT Resources Program serves WSU by creating, maintaining, and strengthening an inclusive and safe campus environment for people of all sexualities, gender identities, and gender expressions through educational programs, advocacy, ally support, peer mentoring, and community outreach","web":"weber.edu/lgbtresourcecenter","tel":"801-626-7271","email":"jaysonstokes@weber.edu","addr":"","fb":"https://www.facebook.com/WeberStateLGBTcenter/?ref=page_internal","ig":""},{"id":"KsWnYuseSBe4u6.Mo4l2.A","name":"West Valley Health Center","cat":"Wellness/Medical","county":"Salt Lake County","counties":["Salt Lake County"],"demo":[],"img":"https://hosting.photobucket.com/images/i/lgbtqut/5f36ad95b2ae3f30b8d8e28b_5f36abc5c9770f898e299192_Planned_20Parenthood.jpeg","desc":"Services Offered:\n\nBirth Control\n\nHIV Services\n\nMen's Health Care\n\nMorning-After Pill (Emergency Contraception)\n\nPregnancy Testing & Services\n\nPrimary Care\n\nSTD Testing, Treatment, & Vaccines\n\nWomen's Health Care\n\nAbortion Referrals\n\nFor more information, hours, and to book online, please visit the Health Center Website.","web":"","tel":"","email":"","addr":"1906 West 3600 South West Valley City, UT 84119","fb":"","ig":""},{"id":"4cHAdg-FRK2UVLQtfD69eQ","name":"Westminster Queer Compass","cat":"College Resources","county":"Salt Lake County","counties":["Salt Lake County"],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5fbd5e9c047dc60f8b1c3314_Westminster%20Queer%20Compass%20(1).png","desc":"Queer Compass is a student-led, administratively supported initiative through the Student Diversity and Inclusion Center that serves the Lesbian, Gay, Bisexual, Transgender, Queer/Questioning, Intersex, Asexual/Ally+ (LGBTQIA+) population on Westminster's campus.This initiative aims to foster community, visibility, and openness within the Westminster community. We host meetings where attendees can participate in multifaceted intersectional dialogues surrounding topics such as marginalization, victimization, safety, power, privilege, identity, gender, sexuality, higher education, and growth.Queer Compass creates a sense of belonging and community for students based on the shared interest and/or identity of queerness. The group provides resources including volunteer opportunities within the LGBTQIA+ community and emotional support in times of need.Gender-Neutral RestroomsWith the generous ","web":"westminstercollege.edu/student-life/student-diversity-and-inclusion-center/queer-compass","tel":"","email":"diversity@westminstercollege.edu","addr":"1840 1300 E #105, Salt Lake City, UT 84105","fb":"https://www.facebook.com/QCatWestminster/","ig":""},{"id":"yiYudwnJQjSZquhi9F7YbA","name":"Women and Non-Binary People Online Community","cat":"Online Community","county":"","counties":[],"demo":["LDS"],"img":"https://hosting.photobucket.com/images/i/lgbtqut/5f663c89dc4ac15aa61147df_novo-logo-afirma_o_n.png","desc":"For Mormon LGBTQIA+/SSA women and non-binary people who have affinity in some aspect with being a woman or being female and being Mormon/LDS in heritage or practice","web":"","tel":"","email":"","addr":"","fb":"https://www.facebook.com/AffirmationWomen?fref=ts","ig":""},{"id":"3GXR-pxGT2OgBGoINLSnuA","name":"WSU Matthew Shepherd Scholarship","cat":"College Resources","county":"","counties":[],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/6114942efa35a781b4d2f0df_athletics_stacked.jpg","desc":"The purpose of this endowed scholarship is to support students at Weber State University who identify as a sexual or gender minority as well as their allies. It is a goal of this scholarship to educate individuals about issues concerning sexual and gender minorities and to create an atmosphere of support and nurturing for all students at Weber State University. \n\nScholarship applications are taken during Spring Semester and scholarships are awarded for the academic year starting in Fall Semester. Scholarship Awards can cover resident tuition, books, fees and other educational expenses. \n\nThe Weber State University Matthew Shepard Scholarship strives to: \n\nBuild awareness of the academic achievements and community service of sexual and gender minority students at Weber State University. \n\n Encourage recipients to complete their studies and become an engaged, supportive community leader.\n\n","web":"weber.edu/lgbtresourcecenter/Matthew_Shepard_Scholarship.html","tel":"801-626-7271","email":"jaysonstokes@weber.edu","addr":"","fb":"","ig":""},{"id":"RYBSszqCT3GDOANhjCmJNg","name":"Youth Activity Night","cat":"Social Groups","county":"Salt Lake County","counties":["Salt Lake County"],"demo":["Youth"],"img":"https://hosting.photobucket.com/images/i/lgbtqut/Logo_-_square.jpg","desc":"Youth Activity Night is a 10-14 age social group. We do a variety of activities, like game nights, craft nights, and speaker nights. An orientation is required.\n\nOrientations can be completed from 3:00 pm-4:30 pm on Mondays, Tuesdays and Fridays.","web":"utahpridecenter.org","tel":"801-539-8800","email":"youth@utahpridecenter.org","addr":"1380 South Main, SLC, UT, 84115","fb":"","ig":""},{"id":"iOFVtRWOSp21e21hCZ9wkw","name":"Youth Futures (Ogden)","cat":"Homeless","county":"Weber County","counties":["Weber County"],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5f663a8a013a6d5cde0ba425_Youth%20Futures.jpg","desc":"Youth Futures (Ogden) provides safe shelter, collaborative resources, respectful guidance and diverse support to homeless, unaccompanied, runaway and at-risk youth in Northern Utah. Youth Futures provides emergency shelter, temporary residence and supportive services for runaway, homeless, unaccompanied and at-risk youth ages 12-18. The shelter is open 24 hours per day.\n\nDrop-In Services (6:30am-8:00pm - Everyday)\n\n- 3 Hot Meals A Day (6:30am, 12pm, 5pm)\n- Access to Hygiene, clothing, food, etc.\n- Meet with a Case Manager\n- Computer Stations\n- Shower Services\n- Laundry Services\n- Transportation Assistance\n- Therapy (Individual/Group/Family) \n- Life Skill Classes \n- Street Outreach: Youth Futures’ Street Outreach is conducted twice per week and provides outreach and crisis services on the streets to youth in Ogden","web":"youthfuturesutah.org","tel":"801-528-1214","email":"info@yfut.org","addr":"2760 Adams Ave Ogden, UT","fb":"","ig":""},{"id":"7tegirC-SKWkpUt.Q4xiTQ","name":"Youth Futures (St. George)","cat":"Homeless","county":"Washington County","counties":["Washington County"],"demo":[],"img":"https://uploads-ssl.webflow.com/5f2ad784e8fae48bcf796a04/5f663a8a013a6d5cde0ba425_Youth%20Futures.jpg","desc":"Youth Futures (St George) provides safe shelter, collaborative resources, respectful guidance and diverse support to homeless, unaccompanied, runaway and at-risk youth in Northern Utah. Youth Futures provides emergency shelter, temporary residence and supportive services for runaway, homeless, unaccompanied and at-risk youth ages 12-18. The shelter is open 24 hours per day.\n\nDrop-In Services (6:30am-8:00pm - Everyday)\n\n- 3 Hot Meals A Day (6:30am, 12pm, 5pm)\n- Access to Hygiene, clothing, food, etc.\n- Meet with a Case Manager\n- Computer Stations\n- Shower Services\n- Laundry Services\n- Transportation Assistance\n- Therapy (Individual/Group/Family) \n- Life Skill Classes \n- Street Outreach: Youth Futures’ Street Outreach is conducted twice per week and provides outreach and crisis services on the streets to youth in St. George","web":"youthfuturesutah.org","tel":"801-528-1214","email":"info@yfut.org","addr":"340 E Tabernacle St, St. George, UT 84770","fb":"","ig":""},{"id":"O8QG0YCwQw2tZbYeNeiusQ","name":"Youth Support Group","cat":"Support Circles","county":"Salt Lake County","counties":["Salt Lake County"],"demo":["Youth"],"img":"https://hosting.photobucket.com/images/i/lgbtqut/Logo_-_square.jpg","desc":"YSG is a peer-led support group that meets weekly on Tuesdays. There are two sessions; the 14-20 age group meets from 6:30 p.m. to 8:00 p.m. and the 10-14 age group meets from 6:00 p.m. – 7:30 p.m. An orientation is required.","web":"utahpridecenter.org/youth-programs","tel":"","email":"","addr":"","fb":"","ig":""},{"id":"kYrVp6sVSOWenGIZvZjSpA","name":"Queerful Counseling","cat":"Mental Health/Counseling","county":"Salt Lake County","counties":["Salt Lake County"],"demo":[],"img":"https://storage.googleapis.com/glide-prod.appspot.com/uploads-v2/NSfaaNV0fRhAK9yZqEUi/pub/3OhaAly5tykKWqIzt9D0.jpg","desc":"#### Mental health therapy specializing in queerness, sex therapy, and Mormon faith transitions.\n\nQueerness, faith transitions, religious trauma, and sex. I can (and do) talk about these topics all day. Any one of these issues can seem overwhelming and impossible to deal with. As a therapist who has dealt with these issues myself, I bring both professional and personal experience to help you move forward. I know every person's story and life is unique and I won't project my experiences on you. However, you won't have to explain the \"Mormon lingo\" or worry that I won't understand the unique issues queer individuals face in a heteronormative and cisgender world.\n\nWhen we meet, I want to make sure I understand you holistically and that you feel heard. I then work collaboratively with you to create a personalized plan moving forward. I can draw from a wide variety of modalities and technique","web":"psychologytoday.com/us/therapists/colette-dalton-sandy-ut/860415","tel":"","email":"","addr":"9571 South 700 East STE #101, Sandy, UT 84070","fb":"","ig":"https://www.instagram.com/queerfulcounseling"},{"id":"xl28gJgnQtqfc67WagG.dg","name":"STARS in Action","cat":"Social Groups","county":"Weber County","counties":["Weber County"],"demo":["Trans"],"img":"https://hosting.photobucket.com/images/i/lgbtqut/OP_STARSBackground.jpg","desc":"Synergetic Trans Activists, Resources & Support\n\nSTARS in Action provides dedicated support for the transgender and gender non-conforming community.\n\n**Our aims:**\n- build community in Ogden through social meetings and events\n- grow our social footprint in our communities through volunteering opportunities\n- provide professional development through workshops and career resources\n- offer resources and support to meet our community’s most pressing needs\n- magnify our presence and programming through partnerships with community organizations.","web":"https://www.ogdenpride.org/ogden-pride-center/stars-in-action/","tel":"","email":"info@ogdenpride.org","addr":"","fb":"https://www.facebook.com/groups/starsinaction/","ig":""},{"id":"TTnviwJ0Sc6NGDj3sXedYg","name":"Neurobehavioral Center for Growth","cat":"Mental Health/Counseling","county":"Davis County","counties":["Davis County","Weber County","Salt Lake County"],"demo":[],"img":"https://storage.googleapis.com/glide-prod.appspot.com/uploads-v2/GLyS34gJTOtHtpGe05Cl/pub/kdwS7CjotvJmt8ItsGgF.png","desc":"## Let’s grow together.\n\nTreatment paths unique to every child, teen, adult, and family.  We believe in celebrating you.\n\nAt NBCG, we offer personalized psychological, developmental, behavioral, and mental health services designed to empower individuals living with an array of complexities.\n\n## We specialize in…","web":"www.neurobcg.com","tel":"801-683-1062","email":"","addr":"","fb":"https://www.facebook.com/neurobcg","ig":"https://www.instagram.com/neurobcg/"}];
